-- Adds full title/dua translations (en, fr, ur, id, ms, hi, tr, bn, ha) to
-- every base dua category, under a per-category 'translations' key — the app
-- falls back to the Arabic original for any language/category not covered.
update public.duas_base
set content = '[{"id": "parents", "title": "دعائي لوالديّ معًا", "icon": "👨‍👩‍👦", "duas": ["رب ارحمهما كما ربياني صغيرا", "ربنا اغفر لي ولوالديّ وللمؤمنين يوم يقوم الحساب", "رب أوزعني أن أشكر نعمتك التي أنعمت عليّ وعلى والديّ وأن أعمل صالحًا ترضاه", "اللهم ارضَ عنهما كما رضيا عنّي صغيرا، وأكرمهما كما أكرماني", "اللهم أطل عمرهما على طاعتك، وارزقهما الصحة والعافية، وبارك لهما في أيامهما", "اللهم اغفر لهما ذنوبهما، وارفع درجتهما، وأكرم نزلهما", "اللهم اجزهما عني خير ما جزى والدًا عن ولده، فلقد ربياني صغيرًا وتعبا عليّ كثيرًا", "اللهم اجمعنا بهما في الفردوس الأعلى من الجنة، مع النبيين والصديقين والشهداء والصالحين", "اللهم لا تحرمني برّهما، ووفقني لطاعتهما فيما يرضيك، واجعلني سببًا في راحة قلبيهما", "اللهم اجعل عملي هذا خالصًا لوجهك، واجعل ثوابه في ميزان حسناتهما", "اللهم إن كانا حيَّين فأطل أعمارهما على طاعتك، وإن كانا قد توفّيا فارحمهما رحمة واسعة واغفر لهما وأدخلهما فسيح جناتك", "اللهم اجعلني بارًّا بوالديّ في حياتهما وبعد مماتهما، ولا تجعلني من العاقين", "اللهم ارزقني رضاهما، فإن رضاك في رضاهما", "اللهم أعنّي على برّهما وطاعتهما، ولا تجعل بيني وبينهما إلا كل خير"], "translations": {"en": {"title": "My Dua for My Parents", "duas": ["My Lord, have mercy upon them as they brought me up when I was small.", "Our Lord, forgive me and my parents and the believers the Day the account is established.", "My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to do righteousness of which You approve.", "O Allah, be pleased with them as they were pleased with me when I was small, and honor them as they honored me.", "O Allah, prolong their lives in obedience to You, grant them health and wellbeing, and bless their days.", "O Allah, forgive their sins, raise their rank, and honor their abode.", "O Allah, reward them on my behalf with the best reward a parent has ever received from a child, for they raised me when I was small and toiled greatly for me.", "O Allah, unite us with them in the highest Paradise, with the prophets, the truthful, the martyrs, and the righteous.", "O Allah, do not deprive me of being dutiful to them, grant me success in obeying them in what pleases You, and make me a means of ease for their hearts.", "O Allah, make this deed of mine purely for Your sake, and place its reward in the scale of their good deeds.", "O Allah, if they are living, prolong their lives in obedience to You; and if they have passed away, grant them abundant mercy, forgive them, and admit them into the vastness of Your Paradise.", "O Allah, make me dutiful to my parents in their life and after their death, and do not make me among those who are undutiful.", "O Allah, grant me their approval, for indeed Your approval lies in theirs.", "O Allah, help me to be dutiful and obedient to them, and let there be nothing between us but good."]}, "fr": {"title": "Ma prière pour mes parents", "duas": ["Seigneur, fais-leur, à tous deux, miséricorde comme ils m''ont élevé tout petit.", "Notre Seigneur, pardonne-moi, ainsi qu''à mes parents et aux croyants, le jour où se dressera le compte.", "Seigneur, inspire-moi de rendre grâce pour Ton bienfait dont Tu m''as comblé, ainsi que mes parents, et de faire une œuvre agréée par Toi.", "Ô Allah, sois satisfait d''eux comme ils l''ont été de moi quand j''étais petit, et honore-les comme ils m''ont honoré.", "Ô Allah, prolonge leur vie dans Ton obéissance, accorde-leur la santé et le bien-être, et bénis leurs jours.", "Ô Allah, pardonne-leur leurs péchés, élève leur rang, et honore leur demeure.", "Ô Allah, récompense-les de ma part par la meilleure récompense qu''un parent ait jamais reçue d''un enfant, car ils m''ont élevé tout petit et se sont beaucoup dévoués pour moi.", "Ô Allah, réunis-nous avec eux au plus haut du Paradis, avec les prophètes, les véridiques, les martyrs et les vertueux.", "Ô Allah, ne me prive pas de leur bienfaisance, accorde-moi de leur obéir en ce qui Te satisfait, et fais de moi une cause d''apaisement pour leurs cœurs.", "Ô Allah, fais que cette œuvre soit sincèrement pour Toi, et place sa récompense dans la balance de leurs bonnes actions.", "Ô Allah, s''ils sont vivants, prolonge leur vie dans Ton obéissance ; et s''ils sont décédés, accorde-leur une vaste miséricorde, pardonne-leur et fais-les entrer dans l''immensité de Ton Paradis.", "Ô Allah, fais de moi quelqu''un de bienfaisant envers mes parents de leur vivant et après leur mort, et ne fais pas de moi quelqu''un d''ingrat envers eux.", "Ô Allah, accorde-moi leur agrément, car Ton agrément se trouve dans le leur.", "Ô Allah, aide-moi à être bienfaisant et obéissant envers eux, et qu''il n''y ait entre nous que du bien."]}, "ur": {"title": "میری دعا اپنے والدین کے لیے", "duas": ["اے میرے رب! ان دونوں پر رحم فرما جس طرح انہوں نے بچپن میں میری پرورش کی۔", "اے ہمارے رب! مجھے، میرے والدین کو اور تمام مومنوں کو اس دن بخش دے جس دن حساب قائم ہوگا۔", "اے میرے رب! مجھے توفیق دے کہ میں تیری اس نعمت کا شکر ادا کروں جو تو نے مجھ پر اور میرے والدین پر کی ہے، اور ایسے نیک عمل کروں جن سے تو راضی ہو۔", "اے اللہ! ان دونوں سے راضی ہو جا جیسے وہ بچپن میں مجھ سے راضی تھے، اور انہیں عزت دے جیسے انہوں نے مجھے عزت دی۔", "اے اللہ! ان کی عمریں اپنی اطاعت میں دراز فرما، انہیں صحت و عافیت عطا فرما، اور ان کے ایام میں برکت عطا فرما۔", "اے اللہ! ان کے گناہ بخش دے، ان کے درجات بلند فرما، اور ان کی قیام گاہ کو باعزت بنا۔", "اے اللہ! انہیں میری طرف سے وہ بہترین جزا عطا فرما جو کسی والدین کو ان کی اولاد کی طرف سے ملی ہو، بیشک انہوں نے مجھے بچپن میں پالا اور میرے لیے بہت تکلیفیں اٹھائیں۔", "اے اللہ! ہمیں ان کے ساتھ جنت الفردوس میں جمع فرما، انبیاء، صدیقین، شہداء اور صالحین کے ساتھ۔", "اے اللہ! مجھے ان کے ساتھ نیکی کرنے سے محروم نہ فرما، مجھے ان کی اطاعت کی توفیق دے جس میں تیری رضا ہو، اور مجھے ان کے دلوں کے سکون کا ذریعہ بنا۔", "اے اللہ! میرے اس عمل کو خالص اپنی رضا کے لیے بنا، اور اس کا اجر ان کے نامہ اعمال میں رکھ دے۔", "اے اللہ! اگر وہ زندہ ہیں تو اپنی اطاعت میں ان کی عمریں دراز فرما، اور اگر وہ وفات پا چکے ہیں تو ان پر اپنی وسیع رحمت فرما، انہیں بخش دے، اور اپنی کشادہ جنتوں میں داخل فرما۔", "اے اللہ! مجھے میرے والدین کی زندگی میں اور ان کی وفات کے بعد بھی ان کا فرمانبردار بنا، اور مجھے نافرمانوں میں شامل نہ فرما۔", "اے اللہ! مجھے ان کی رضا نصیب فرما، کیونکہ تیری رضا انہی کی رضا میں ہے۔", "اے اللہ! ان کے ساتھ نیکی اور اطاعت میں میری مدد فرما، اور ہمارے درمیان بھلائی کے سوا کچھ نہ رکھ۔"]}, "id": {"title": "Doaku untuk Kedua Orang Tuaku", "duas": ["Ya Tuhanku, sayangilah keduanya sebagaimana mereka berdua telah mendidikku pada waktu kecil.", "Ya Tuhan kami, ampunilah aku dan kedua orang tuaku serta semua orang yang beriman pada hari terjadinya hisab (hari kiamat).", "Ya Tuhanku, tunjukilah aku untuk mensyukuri nikmat-Mu yang telah Engkau berikan kepadaku dan kepada kedua orang tuaku, dan agar aku dapat berbuat kebajikan yang Engkau ridai.", "Ya Allah, ridailah keduanya sebagaimana mereka meridaiku ketika aku masih kecil, dan muliakanlah keduanya sebagaimana mereka memuliakanku.", "Ya Allah, panjangkanlah umur keduanya dalam ketaatan kepada-Mu, karuniakanlah kepada mereka kesehatan dan keselamatan, dan berkahilah hari-hari mereka.", "Ya Allah, ampunilah dosa-dosa keduanya, angkatlah derajat mereka, dan muliakanlah tempat tinggal mereka.", "Ya Allah, balaslah kebaikan keduanya untukku dengan sebaik-baik balasan yang pernah Engkau berikan kepada orang tua dari anaknya, karena mereka telah mendidikku sejak kecil dan bersusah payah demi diriku.", "Ya Allah, kumpulkanlah kami bersama mereka di surga Firdaus yang tertinggi, bersama para nabi, orang-orang yang jujur, para syuhada, dan orang-orang saleh.", "Ya Allah, jangan halangi aku dari berbakti kepada keduanya, berilah aku taufik untuk menaati mereka dalam hal yang Engkau ridai, dan jadikanlah aku sebab ketenangan hati mereka.", "Ya Allah, jadikanlah amal ini ikhlas karena wajah-Mu, dan jadikanlah pahalanya di dalam timbangan kebaikan keduanya.", "Ya Allah, jika keduanya masih hidup, panjangkanlah umur mereka dalam ketaatan kepada-Mu; dan jika keduanya telah wafat, limpahkanlah rahmat yang luas kepada mereka, ampunilah mereka, dan masukkanlah mereka ke dalam surga-Mu yang luas.", "Ya Allah, jadikanlah aku anak yang berbakti kepada kedua orang tuaku semasa hidup maupun setelah wafat mereka, dan jangan jadikan aku termasuk orang-orang yang durhaka.", "Ya Allah, karuniakanlah kepadaku keridaan keduanya, karena sesungguhnya keridaan-Mu ada dalam keridaan mereka.", "Ya Allah, tolonglah aku untuk berbakti dan menaati keduanya, dan jangan jadikan di antara kami kecuali kebaikan."]}, "ms": {"title": "Doaku untuk Kedua Ibu Bapaku", "duas": ["Wahai Tuhanku, kasihanilah kedua-duanya sebagaimana mereka mendidikku sewaktu kecil.", "Wahai Tuhan kami, ampunkanlah aku, kedua ibu bapaku, dan sekalian orang beriman pada hari hisab (perhitungan) ditegakkan.", "Wahai Tuhanku, ilhamkanlah daku supaya tetap bersyukur akan nikmat-Mu yang telah Engkau kurniakan kepadaku dan kepada kedua ibu bapaku, dan supaya aku sentiasa mengerjakan amal soleh yang Engkau redai.", "Ya Allah, redhailah kedua-duanya sebagaimana mereka redha kepadaku semasa aku kecil, dan muliakanlah mereka sebagaimana mereka memuliakanku.", "Ya Allah, panjangkanlah umur mereka dalam ketaatan kepada-Mu, kurniakanlah kesihatan dan kesejahteraan kepada mereka, serta berkatilah hari-hari mereka.", "Ya Allah, ampunilah dosa-dosa mereka, tinggikanlah darjat mereka, dan muliakanlah tempat kembali mereka.", "Ya Allah, balaslah jasa mereka bagi pihakku dengan sebaik-baik balasan yang pernah diterima seorang ibu bapa daripada anaknya, kerana mereka telah mendidikku sewaktu kecil dan bersusah payah demi diriku.", "Ya Allah, kumpulkanlah kami bersama mereka di syurga Firdaus yang tertinggi, bersama para nabi, orang-orang yang benar, para syuhada, dan orang-orang soleh.", "Ya Allah, janganlah Engkau haramkan aku daripada berbakti kepada mereka, berikanlah aku taufik untuk mentaati mereka dalam perkara yang Engkau redai, dan jadikanlah aku punca ketenangan hati mereka.", "Ya Allah, jadikanlah amalanku ini ikhlas kerana-Mu semata-mata, dan letakkanlah pahalanya dalam timbangan kebaikan mereka.", "Ya Allah, jika mereka masih hidup, panjangkanlah umur mereka dalam ketaatan kepada-Mu; dan jika mereka telah wafat, kurniakanlah rahmat yang luas kepada mereka, ampunilah mereka, dan masukkanlah mereka ke dalam syurga-Mu yang luas.", "Ya Allah, jadikanlah aku seorang anak yang berbakti kepada kedua ibu bapaku semasa hidup mereka dan selepas kewafatan mereka, dan janganlah Engkau jadikan aku daripada golongan yang derhaka.", "Ya Allah, kurniakanlah aku keredaan mereka, kerana sesungguhnya keredaan-Mu terletak pada keredaan mereka.", "Ya Allah, bantulah aku untuk berbakti dan taat kepada mereka, dan jangan jadikan antara kami melainkan kebaikan semata-mata."]}, "hi": {"title": "अपने माता-पिता दोनों के लिए मेरी दुआ", "duas": ["मेरे रब! उन दोनों पर रहम फ़रमा, जैसे उन्होंने बचपन में मेरी परवरिश की।", "ऐ हमारे रब! मुझे, मेरे माता-पिता को और मोमिनों को उस दिन बख़्श दे जिस दिन हिसाब क़ायम होगा।", "हे मेरे रब! मुझे तौफ़ीक़ दे कि मैं तेरी उस नेमत का शुक्र अदा करूँ जो तूने मुझ पर और मेरे माता-पिता पर की है, और यह कि मैं ऐसा नेक अमल करूँ जिसे तू पसंद करे।", "हे अल्लाह! उन दोनों से उसी तरह राज़ी हो जा जैसे वे बचपन में मुझसे राज़ी थे, और उन्हें उसी तरह इज़्ज़त दे जैसे उन्होंने मुझे इज़्ज़त दी।", "हे अल्लाह! उनकी उम्र तेरी इताअत में लंबी कर, उन्हें सेहत और आफ़ियत अता कर, और उनके दिनों में बरकत दे।", "हे अल्लाह! उनके गुनाह बख़्श दे, उनका दर्जा बुलंद कर, और उनकी मंज़िल को इज़्ज़त वाला बना।", "हे अल्लाह! मेरी तरफ़ से उन्हें उससे बेहतर बदला दे जो किसी वालिद को अपनी औलाद से मिला हो, क्योंकि उन्होंने बचपन में मेरी परवरिश की और मेरे लिए बहुत मेहनत उठाई।", "हे अल्लाह! हमें जन्नत के सबसे ऊँचे दर्जे फ़िरदौस में उनके साथ इकट्ठा कर, नबियों, सिद्दीक़ीन, शहीदों और नेक लोगों के साथ।", "हे अल्लाह! मुझे उनकी सेवा से महरूम न रख, मुझे उनकी उस इताअत की तौफ़ीक़ दे जो तुझे पसंद हो, और मुझे उनके दिलों के सुकून का सबब बना।", "हे अल्लाह! मेरे इस अमल को ख़ालिस अपनी रज़ा के लिए बना, और इसका सवाब उनकी नेकियों के तराज़ू में रख।", "हे अल्लाह! अगर वे ज़िंदा हैं तो उनकी उम्र तेरी इताअत में लंबी कर, और अगर उनका इंतक़ाल हो चुका है तो उन पर अपनी वसीअ रहमत फ़रमा, उन्हें बख़्श दे और अपनी जन्नत की वुसअत में दाख़िल कर।", "हे अल्लाह! मुझे अपने माता-पिता का नेक बेटा बना, उनकी ज़िंदगी में भी और उनकी मौत के बाद भी, और मुझे नाफ़रमानों में शामिल न कर।", "हे अल्लाह! मुझे उनकी रज़ामंदी अता कर, क्योंकि तेरी रज़ा उन्हीं की रज़ा में है।", "हे अल्लाह! उनकी सेवा और इताअत में मेरी मदद फ़रमा, और मेरे और उनके बीच सिर्फ़ भलाई रख।"]}, "tr": {"title": "Anne Babam İçin Duam", "duas": ["Rabbim, onlar beni küçükken yetiştirdikleri gibi, sen de onlara merhamet eyle.", "Rabbimiz! Hesabın görüleceği gün beni, anne babamı ve müminleri bağışla.", "Rabbim! Bana ve anne babama verdiğin nimete şükretmemi ve senin razı olacağın salih ameli işlememi bana ilham et.", "Allah''ım! Onlar küçükken benden razı oldukları gibi sen de onlardan razı ol, beni onurlandırdıkları gibi sen de onları onurlandır.", "Allah''ım! Onların ömürlerini sana itaat üzere uzun eyle, onlara sağlık ve afiyet ver, günlerini bereketli kıl.", "Allah''ım! Onların günahlarını bağışla, derecelerini yükselt, konaklama yerlerini şerefli kıl.", "Allah''ım! Bir babaya evladından verilebilecek en hayırlı karşılığı onlara benden ver; çünkü onlar beni küçükken büyüttüler ve benim için çok yorulup emek verdiler.", "Allah''ım! Bizi onlarla birlikte cennetin en yüksek makamı olan Firdevs''te, peygamberler, sıddîklar, şehidler ve salihlerle bir araya getir.", "Allah''ım! Beni onlara iyilik etmekten mahrum bırakma, seni razı edecek şekilde onlara itaat etmeyi bana nasip et ve beni kalplerinin huzuru için bir vesile kıl.", "Allah''ım! Bu amelimi sadece senin rızan için halis kıl ve sevabını onların hasenat terazisine koy.", "Allah''ım! Eğer hayatta iseler ömürlerini sana itaat üzere uzun eyle; vefat etmişlerse onlara geniş bir rahmetle merhamet et, onları bağışla ve onları cennetinin genişliğine kabul et.", "Allah''ım! Beni hayatlarında ve vefatlarından sonra anne babama iyilik eden biri kıl, beni onlara asi olanlardan eyleme.", "Allah''ım! Bana onların rızasını nasip et; çünkü senin rızan onların rızasındadır.", "Allah''ım! Onlara iyilik etmemde ve itaat etmemde bana yardım et, aramızda hayırdan başka bir şey bırakma."]}, "bn": {"title": "আমার পিতা-মাতার জন্য দোয়া", "duas": ["হে আমার প্রতিপালক! আপনি তাদের প্রতি দয়া করুন, যেভাবে তারা শৈশবে আমাকে লালন-পালন করেছেন।", "হে আমাদের প্রতিপালক! আপনি আমাকে, আমার পিতা-মাতাকে এবং মুমিনদেরকে ক্ষমা করুন, যেদিন হিসাব সংঘটিত হবে।", "হে আমার প্রতিপালক! আমাকে তাওফিক দিন যেন আমি আপনার সেই নিয়ামতের শুকরিয়া আদায় করতে পারি, যা আপনি আমাকে ও আমার পিতা-মাতাকে দান করেছেন, এবং যেন আমি এমন সৎকাজ করতে পারি যা আপনি পছন্দ করেন।", "হে আল্লাহ, আপনি তাদের প্রতি সন্তুষ্ট হোন, যেমন তারা আমার শৈশবে আমার প্রতি সন্তুষ্ট ছিলেন, এবং তাদেরকে সম্মানিত করুন, যেমন তারা আমাকে সম্মানিত করেছেন।", "হে আল্লাহ, তাদের হায়াতকে আপনার আনুগত্যে দীর্ঘায়িত করুন, তাদেরকে সুস্থতা ও নিরাপত্তা দান করুন, এবং তাদের দিনগুলোতে বরকত দিন।", "হে আল্লাহ, তাদের গুনাহ ক্ষমা করুন, তাদের মর্যাদা উঁচু করুন এবং তাদের আবাসস্থলকে সম্মানিত করুন।", "হে আল্লাহ, আমার পক্ষ থেকে তাদেরকে এমন উত্তম প্রতিদান দিন, যা কোনো সন্তান তার পিতা-মাতার জন্য দিতে পেরেছে তার চেয়েও উত্তম; কেননা তারা আমাকে শৈশবে লালন-পালন করেছেন এবং আমার জন্য অনেক কষ্ট স্বীকার করেছেন।", "হে আল্লাহ, আমাদেরকে তাদের সাথে জান্নাতের সর্বোচ্চ স্তর ফিরদাউসে একত্র করুন, নবীগণ, সিদ্দিকীনগণ, শহীদগণ ও সালিহীনদের সাথে।", "হে আল্লাহ, আমাকে তাদের সেবা করার সুযোগ থেকে বঞ্চিত করবেন না, আপনাকে সন্তুষ্ট করে এমনভাবে তাদের আনুগত্য করার তাওফিক দিন, এবং আমাকে তাদের হৃদয়ের প্রশান্তির উপলক্ষ বানান।", "হে আল্লাহ, আমার এই আমলকে একান্তভাবে আপনার সন্তুষ্টির জন্য কবুল করুন, এবং এর প্রতিদান তাদের নেকীর পাল্লায় রাখুন।", "হে আল্লাহ, যদি তারা জীবিত থাকেন, তবে তাদের হায়াতকে আপনার আনুগত্যে দীর্ঘায়িত করুন; আর যদি তারা ইন্তেকাল করে থাকেন, তবে তাদেরকে ব্যাপক রহমত দান করুন, তাদেরকে ক্ষমা করুন এবং তাদেরকে আপনার প্রশস্ত জান্নাতে প্রবেশ করান।", "হে আল্লাহ, আমাকে আমার পিতা-মাতার জীবদ্দশায় ও মৃত্যুর পরও তাদের অনুগত সন্তান বানান, এবং আমাকে তাদের অবাধ্যদের অন্তর্ভুক্ত করবেন না।", "হে আল্লাহ, আমাকে তাদের সন্তুষ্টি দান করুন, কেননা আপনার সন্তুষ্টি নিহিত রয়েছে তাদের সন্তুষ্টির মধ্যে।", "হে আল্লাহ, তাদের সেবা ও আনুগত্য করতে আমাকে সাহায্য করুন, এবং আমার ও তাদের মাঝে কল্যাণ ছাড়া অন্য কিছু রাখবেন না।"]}, "ha": {"title": "Addu''ata Ga Iyayena", "duas": ["Ya Ubangijina, ka yi musu rahama kamar yadda suka rene ni tun ina karama.", "Ya Ubangijinmu, ka gafarta mini da iyayena da kuma muminai a ranar da za a tsayar da hisabi.", "Ya Ubangijina, ka yi mini ilhami in gode wa ni''imarka wadda ka yi mini da iyayena, kuma in aikata aiki na kwarai wanda kake yarda da shi.", "Ya Allah, ka yarda da su kamar yadda suka yarda da ni tun ina karama, kuma ka girmama su kamar yadda suka girmama ni.", "Ya Allah, ka tsawaita rayuwarsu a kan yin biyayya gare ka, ka azurta su da lafiya da koshin lafiya, kuma ka sa albarka a kwanakinsu.", "Ya Allah, ka gafarta musu zunubansu, ka daukaka darajarsu, kuma ka girmama masaukinsu.", "Ya Allah, ka saka musu sakayya mafi kyau da Ka taba saka wa iyaye daga yaransu, domin sun rene ni tun ina karama, kuma sun sha wahala matuka a kaina.", "Ya Allah, ka tara mu da su a Firdausi mafi daukaka na Aljanna, tare da annabawa da masu gaskiya da shahidai da salihai.", "Ya Allah, kada Ka hana ni yin biyayya gare su, ka ba ni ikon yin biyayya gare su a cikin abin da yake faranta maka rai, kuma ka sanya ni dalilin natsuwar zuciyarsu.", "Ya Allah, ka sanya wannan aikina na tsantsa saboda Kai, kuma ka sanya ladansa a ma''aunin ayyukansu na kwarai.", "Ya Allah, idan suna raye, ka tsawaita rayuwarsu a kan biyayya gare ka; idan kuwa sun rasu, ka yi musu rahama mai fadi, ka gafarta musu, kuma ka shigar da su cikin fadin Aljannarka.", "Ya Allah, ka sanya ni mai biyayya ga iyayena a rayuwarsu da bayan mutuwarsu, kuma kada Ka sanya ni cikin marasa biyayya.", "Ya Allah, ka azurta ni da yardarsu, domin yardarka tana cikin yardarsu.", "Ya Allah, ka taimake ni in yi musu biyayya da bin umarninsu, kuma kada Ka sanya tsakanina da su face alheri kawai."]}}}, {"id": "self", "title": "دعائي لنفسي", "icon": "🧕", "duas": ["اللهم اجعلني ممن يذكرك كثيرًا ويشكرك كثيرًا ويخشاك كثيرًا ويطيعك كثيرًا", "اللهم إني أسألك الهدى والتقى والعفاف والغنى", "اللهم أصلح لي ديني الذي هو عصمة أمري، وأصلح لي دنياي التي فيها معاشي، وأصلح لي آخرتي التي فيها معادي", "رب اشرح لي صدري ويسر لي أمري", "اللهم رحمتك أرجو فلا تكلني إلى نفسي طرفة عين، وأصلح لي شأني كله، لا إله إلا أنت", "اللهم ثبّتني على دينك حتى ألقاك وأنت راضٍ عني", "اللهم اجعل خير عمري آخره، وخير عملي خواتمه، وخير أيامي يوم ألقاك"], "translations": {"en": {"title": "My Dua for Myself", "duas": ["O Allah, make me among those who remember You much, thank You much, fear You much, and obey You much.", "O Allah, I ask You for guidance, piety, chastity, and self-sufficiency.", "O Allah, set right for me my religion, which is the safeguard of my affairs; set right for me my worldly life, in which is my livelihood; and set right for me my Hereafter, to which is my return.", "My Lord, expand for me my breast and ease for me my task.", "O Allah, it is Your mercy I hope for, so do not leave me to myself even for the blink of an eye, and set right all of my affairs. There is no god but You.", "O Allah, keep me firm upon Your religion until I meet You while You are pleased with me.", "O Allah, make the best of my life its end, the best of my deeds their conclusion, and the best of my days the day I meet You."]}, "fr": {"title": "Ma prière pour moi-même", "duas": ["Ô Allah, fais de moi l''un de ceux qui T''invoquent beaucoup, Te remercient beaucoup, Te craignent beaucoup et T''obéissent beaucoup.", "Ô Allah, je Te demande la guidance, la piété, la chasteté et la suffisance.", "Ô Allah, améliore pour moi ma religion qui est la sauvegarde de mes affaires ; améliore pour moi ma vie d''ici-bas où se trouve ma subsistance ; et améliore pour moi mon au-delà vers lequel est mon retour.", "Seigneur, ouvre pour moi ma poitrine et facilite ma tâche.", "Ô Allah, c''est Ta miséricorde que j''espère, ne me laisse pas à moi-même ne serait-ce qu''un clin d''œil, et améliore toutes mes affaires. Il n''y a de divinité que Toi.", "Ô Allah, affermis-moi dans Ta religion jusqu''à ce que je Te rencontre alors que Tu es satisfait de moi.", "Ô Allah, fais que le meilleur de ma vie en soit la fin, que le meilleur de mes œuvres en soit la conclusion, et que le meilleur de mes jours soit celui où je Te rencontrerai."]}, "ur": {"title": "میری دعا اپنے لیے", "duas": ["اے اللہ! مجھے ان لوگوں میں شامل فرما جو تجھے کثرت سے یاد کرتے ہیں، تیرا بہت شکر ادا کرتے ہیں، تجھ سے بہت ڈرتے ہیں اور تیری بہت اطاعت کرتے ہیں۔", "اے اللہ! میں تجھ سے ہدایت، تقویٰ، پاکدامنی اور بے نیازی مانگتا ہوں۔", "اے اللہ! میرے دین کی اصلاح فرما جو میرے تمام معاملات کی حفاظت کا ذریعہ ہے، میری دنیا کی اصلاح فرما جس میں میری روزی ہے، اور میری آخرت کی اصلاح فرما جہاں مجھے لوٹ کر جانا ہے۔", "اے میرے رب! میرا سینہ کھول دے اور میرا کام میرے لیے آسان فرما۔", "اے اللہ! مجھے تیری ہی رحمت کی امید ہے، مجھے ایک پلک جھپکنے کے برابر بھی میرے نفس کے حوالے نہ کر، اور میرے تمام معاملات درست فرما، تیرے سوا کوئی معبود نہیں۔", "اے اللہ! مجھے اپنے دین پر ثابت قدم رکھ یہاں تک کہ میں تجھ سے اس حال میں ملوں کہ تو مجھ سے راضی ہو۔", "اے اللہ! میری زندگی کا بہترین حصہ اس کا آخری حصہ بنا، میرے اعمال کا بہترین حصہ اس کا اختتام بنا، اور میرے دنوں میں بہترین دن وہ بنا جس دن میں تجھ سے ملوں۔"]}, "id": {"title": "Doaku untuk Diriku Sendiri", "duas": ["Ya Allah, jadikanlah aku termasuk orang yang banyak mengingat-Mu, banyak bersyukur kepada-Mu, banyak takut kepada-Mu, dan banyak menaati-Mu.", "Ya Allah, aku memohon kepada-Mu petunjuk, ketakwaan, kesucian diri, dan kecukupan.", "Ya Allah, perbaikilah agamaku yang menjadi penjaga urusanku, perbaikilah duniaku yang menjadi tempat kehidupanku, dan perbaikilah akhiratku yang menjadi tempat kembaliku.", "Ya Tuhanku, lapangkanlah dadaku dan mudahkanlah urusanku.", "Ya Allah, hanya rahmat-Mu yang kuharapkan, maka janganlah Engkau serahkan diriku kepada diriku sendiri walau sekejap mata, dan perbaikilah seluruh urusanku. Tidak ada tuhan yang berhak disembah selain Engkau.", "Ya Allah, teguhkanlah aku di atas agama-Mu hingga aku menjumpai-Mu dalam keadaan Engkau rida kepadaku.", "Ya Allah, jadikanlah sebaik-baik usiaku di penghujungnya, sebaik-baik amalku di akhirnya, dan sebaik-baik hariku adalah hari aku berjumpa dengan-Mu."]}, "ms": {"title": "Doaku untuk Diriku Sendiri", "duas": ["Ya Allah, jadikanlah aku antara mereka yang banyak mengingati-Mu, banyak bersyukur kepada-Mu, banyak takut kepada-Mu, dan banyak taat kepada-Mu.", "Ya Allah, aku memohon kepada-Mu petunjuk, ketakwaan, kesucian diri, dan kecukupan hati.", "Ya Allah, perbaikilah agamaku yang menjadi benteng urusanku, perbaikilah duniaku yang menjadi tempat kehidupanku, dan perbaikilah akhiratku yang menjadi tempat kembaliku.", "Wahai Tuhanku, lapangkanlah dadaku dan mudahkanlah urusanku.", "Ya Allah, hanya rahmat-Mu yang aku harapkan, maka janganlah Engkau serahkan urusanku kepada diriku sendiri walau sekelip mata, dan perbaikilah segala urusanku. Tiada tuhan yang berhak disembah melainkan Engkau.", "Ya Allah, teguhkanlah aku di atas agama-Mu sehingga aku menemui-Mu dalam keadaan Engkau redha kepadaku.", "Ya Allah, jadikanlah sebaik-baik umurku pada penghujungnya, sebaik-baik amalanku pada penutupnya, dan sebaik-baik hariku pada hari aku menemui-Mu."]}, "hi": {"title": "अपने लिए मेरी दुआ", "duas": ["हे अल्लाह! मुझे उन लोगों में शामिल कर जो तुझे बहुत याद करते हैं, तेरा बहुत शुक्र अदा करते हैं, तुझसे बहुत डरते हैं और तेरी बहुत इताअत करते हैं।", "हे अल्लाह! मैं तुझसे हिदायत, तक़वा, पाकदामनी और बेनियाज़ी माँगता हूँ।", "हे अल्लाह! मेरे दीन को दुरुस्त कर दे जो मेरे हर मामले की हिफ़ाज़त है, मेरी दुनिया को दुरुस्त कर दे जिसमें मेरी रोज़ी-रोटी है, और मेरी आख़िरत को दुरुस्त कर दे जिसकी तरफ़ मुझे लौटना है।", "मेरे रब! मेरा सीना खोल दे और मेरे काम को मेरे लिए आसान कर दे।", "हे अल्लाह! मुझे तेरी रहमत की उम्मीद है, इसलिए मुझे पलक झपकने भर के लिए भी मेरे हाल पर न छोड़, और मेरे सारे मामले सँवार दे। तेरे सिवा कोई माबूद नहीं।", "हे अल्लाह! मुझे अपने दीन पर जमाए रख यहाँ तक कि मैं तुझसे इस हाल में मिलूँ कि तू मुझसे राज़ी हो।", "हे अल्लाह! मेरी ज़िंदगी का सबसे अच्छा हिस्सा उसका आख़िरी हिस्सा बना दे, मेरे अमल का सबसे अच्छा हिस्सा उसका अंत बना दे, और मेरे दिनों में सबसे अच्छा दिन वह बना दे जिस दिन मैं तुझसे मिलूँ।"]}, "tr": {"title": "Kendim İçin Duam", "duas": ["Allah''ım! Beni seni çokça zikreden, çokça şükreden, senden çokça korkan ve sana çokça itaat edenlerden eyle.", "Allah''ım! Senden hidayet, takva, iffet ve gönül zenginliği isterim.", "Allah''ım! Sığınağım olan dinimi benim için düzelt, geçimimin kaynağı olan dünyamı benim için düzelt, dönüş yerim olan ahiretimi benim için düzelt.", "Rabbim! Göğsümü genişlet, işimi kolaylaştır.", "Allah''ım! Rahmetini umarım, beni göz açıp kapayıncaya kadar bile nefsime bırakma, bütün işlerimi benim için düzelt. Senden başka ilah yoktur.", "Allah''ım! Sana kavuşuncaya kadar beni dinin üzere sabit kıl; öyle ki sen benden razı olasın.", "Allah''ım! Ömrümün en hayırlısını sonunu, amellerimin en hayırlısını nihayetini, günlerimin en hayırlısını sana kavuşacağım günü kıl."]}, "bn": {"title": "আমার নিজের জন্য দোয়া", "duas": ["হে আল্লাহ, আমাকে তাদের অন্তর্ভুক্ত করুন যারা আপনাকে অধিক স্মরণ করে, অধিক শুকরিয়া আদায় করে, অধিক ভয় করে এবং অধিক আনুগত্য করে।", "হে আল্লাহ, আমি আপনার কাছে হিদায়াত, তাকওয়া, চারিত্রিক পবিত্রতা ও অভাবমুক্তি প্রার্থনা করছি।", "হে আল্লাহ, আমার দ্বীনকে সংশোধন করে দিন, যা আমার সকল বিষয়ের সুরক্ষাকারী; আমার দুনিয়াকে সংশোধন করে দিন, যেখানে আমার জীবিকা নিহিত; এবং আমার আখিরাতকে সংশোধন করে দিন, যেখানে আমার প্রত্যাবর্তন।", "হে আমার প্রতিপালক! আমার বক্ষ প্রশস্ত করে দিন এবং আমার কাজ সহজ করে দিন।", "হে আল্লাহ, আমি আপনার রহমতের আশা রাখি, সুতরাং আমাকে চোখের পলক ফেলার জন্যও আমার নিজের হাতে ছেড়ে দেবেন না, এবং আমার সকল বিষয় সংশোধন করে দিন। আপনি ছাড়া কোনো ইলাহ নেই।", "হে আল্লাহ, আমাকে আপনার দ্বীনের উপর অবিচল রাখুন, যতক্ষণ না আমি আপনার সাথে সাক্ষাৎ করি এমন অবস্থায় যে আপনি আমার প্রতি সন্তুষ্ট।", "হে আল্লাহ, আমার জীবনের সর্বোত্তম অংশ তার শেষভাগে রাখুন, আমার আমলের সর্বোত্তম অংশ তার শেষ পরিণতিতে রাখুন, এবং আমার দিনগুলোর সর্বোত্তম দিন সেই দিন রাখুন যেদিন আমি আপনার সাথে সাক্ষাৎ করব।"]}, "ha": {"title": "Addu''ata Ga Kaina", "duas": ["Ya Allah, ka sanya ni cikin wadanda suke tunawa da Kai da yawa, suke gode maka da yawa, suke tsoron ka da yawa, kuma suke yi maka biyayya da yawa.", "Ya Allah, ina rokon ka shiriya da taqawa da tsarkin zuciya da wadata.", "Ya Allah, ka gyara mini addinina wanda shi ne kariyar al''amarina, ka gyara mini duniyata wadda a cikinta rayuwata take, kuma ka gyara mini lahirata wadda a cikinta makomata take.", "Ya Ubangijina, ka fadada mini kirjina, ka sauwake mini al''amarina.", "Ya Allah, rahamarka nake fata, saboda haka kada Ka bar ni ga kaina ko na dan lokaci kadan, kuma ka gyara mini dukkan al''amarina. Babu abin bautawa da gaskiya sai Kai.", "Ya Allah, ka tabbatar da ni a kan addininka har in hadu da Kai alhali kana yarda da ni.", "Ya Allah, ka sanya mafi alherin rayuwata karshenta, mafi alherin aikina karshensa, kuma mafi alherin kwanakina ranar da zan hadu da Kai."]}}}, {"id": "wife", "title": "دعائي لزوجتي", "icon": "💞", "duas": ["ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إماما", "اللهم ألّف بين قلبينا، واجعل بيننا مودة ورحمة دائمة", "اللهم اجعلها قرة عين لي، وأعنّي على أن أكون خير رفيق لها", "اللهم رب الناس أذهب البأس، اشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقما", "اللهم احفظ سعادتنا وبيتنا، وارزقنا التفاهم والرضا فيما بيننا"], "translations": {"en": {"title": "My Dua for My Wife", "duas": ["Our Lord, grant us from among our spouses and offspring comfort to our eyes and make us leaders for the righteous.", "O Allah, unite our hearts, and place between us lasting love and mercy.", "O Allah, make her a comfort to my eyes, and help me to be the best companion to her.", "O Allah, Lord of mankind, remove the affliction and heal, for You are the Healer. There is no healing but Your healing, a healing that leaves no illness behind.", "O Allah, protect our happiness and our home, and grant us mutual understanding and contentment between us."]}, "fr": {"title": "Ma prière pour mon épouse", "duas": ["Notre Seigneur, accorde-nous, de nos épouses et de nos descendants, la fraîcheur des yeux, et fais de nous un modèle pour les pieux.", "Ô Allah, unis nos deux cœurs, et place entre nous un amour et une miséricorde durables.", "Ô Allah, fais d''elle une fraîcheur pour mes yeux, et aide-moi à être le meilleur compagnon pour elle.", "Ô Allah, Seigneur des hommes, dissipe le mal et guéris, car c''est Toi le Guérisseur. Il n''y a de guérison que la Tienne, une guérison qui ne laisse aucune maladie.", "Ô Allah, préserve notre bonheur et notre foyer, et accorde-nous l''entente et la satisfaction mutuelles."]}, "ur": {"title": "میری دعا اپنی بیوی کے لیے", "duas": ["اے ہمارے رب! ہمیں اپنی بیویوں اور اولاد سے آنکھوں کی ٹھنڈک عطا فرما، اور ہمیں پرہیزگاروں کا امام بنا۔", "اے اللہ! ہمارے دلوں میں محبت پیدا فرما، اور ہمارے درمیان ہمیشہ محبت اور رحمت قائم رکھ۔", "اے اللہ! اسے میری آنکھوں کی ٹھنڈک بنا، اور مجھے اس کا بہترین ساتھی بننے میں مدد فرما۔", "اے اللہ! لوگوں کے رب! تکلیف دور فرما اور شفا عطا فرما، تو ہی شفا دینے والا ہے، تیری شفا کے سوا کوئی شفا نہیں، ایسی شفا جو کوئی مرض باقی نہ چھوڑے۔", "اے اللہ! ہماری خوشیوں اور ہمارے گھر کی حفاظت فرما، اور ہمارے درمیان باہمی افہام و تفہیم اور رضامندی عطا فرما۔"]}, "id": {"title": "Doaku untuk Istriku", "duas": ["Ya Tuhan kami, anugerahkanlah kepada kami pasangan kami dan keturunan kami sebagai penyenang hati, dan jadikanlah kami pemimpin bagi orang-orang yang bertakwa.", "Ya Allah, satukanlah hati kami berdua, dan jadikanlah di antara kami cinta dan kasih sayang yang abadi.", "Ya Allah, jadikanlah dia penyejuk mataku, dan bantulah aku agar menjadi sebaik-baik pendamping baginya.", "Ya Allah, Tuhan manusia, hilangkanlah penyakit ini, sembuhkanlah, Engkaulah Yang Maha Menyembuhkan, tidak ada kesembuhan kecuali kesembuhan dari-Mu, kesembuhan yang tidak meninggalkan penyakit.", "Ya Allah, jagalah kebahagiaan dan rumah tangga kami, dan karuniakanlah kepada kami saling pengertian dan kerelaan di antara kami."]}, "ms": {"title": "Doaku untuk Isteriku", "duas": ["Wahai Tuhan kami, kurniakanlah kepada kami pasangan dan zuriat kami sebagai penyejuk mata, dan jadikanlah kami imam bagi orang-orang yang bertakwa.", "Ya Allah, satukanlah hati kami berdua, dan jadikanlah antara kami mawaddah (kasih sayang) dan rahmat yang kekal.", "Ya Allah, jadikanlah dia penyejuk mataku, dan bantulah aku menjadi sebaik-baik pasangan baginya.", "Ya Allah, Tuhan sekalian manusia, hilangkanlah kesakitan ini, sembuhkanlah, Engkaulah Yang Maha Menyembuhkan, tiada kesembuhan melainkan kesembuhan daripada-Mu, kesembuhan yang tidak meninggalkan sebarang penyakit.", "Ya Allah, peliharalah kebahagiaan dan rumah tangga kami, serta kurniakanlah kami saling memahami dan keredaan antara kami."]}, "hi": {"title": "अपनी पत्नी के लिए मेरी दुआ", "duas": ["ऐ हमारे रब! हमें अपनी बीवियों और औलाद की तरफ़ से आँखों की ठंडक अता कर, और हमें परहेज़गारों का इमाम बना।", "हे अल्लाह! हम दोनों के दिलों में उल्फ़त डाल दे, और हमारे बीच हमेशा रहने वाली मोहब्बत और रहमत रख।", "हे अल्लाह! उसे मेरी आँखों की ठंडक बना, और मेरी मदद फ़रमा कि मैं उसका सबसे अच्छा साथी बनूँ।", "हे अल्लाह! लोगों के रब! तकलीफ़ को दूर कर दे, शिफ़ा दे, तू ही शिफ़ा देने वाला है, तेरी शिफ़ा के सिवा कोई शिफ़ा नहीं, ऐसी शिफ़ा जो कोई बीमारी बाक़ी न छोड़े।", "हे अल्लाह! हमारी ख़ुशी और हमारे घर की हिफ़ाज़त फ़रमा, और हमारे बीच समझ और रज़ामंदी अता कर।"]}, "tr": {"title": "Eşim İçin Duam", "duas": ["Rabbimiz! Eşlerimizi ve çocuklarımızı bize göz aydınlığı kıl ve bizi takva sahiplerine önder eyle.", "Allah''ım! Kalplerimizi birleştir, aramıza kalıcı bir sevgi ve merhamet koy.", "Allah''ım! Onu bana göz aydınlığı kıl, ona en hayırlı eş olmam için bana yardım et.", "Allah''ım! Ey insanların Rabbi! Sıkıntıyı gider, şifa ver, sen şifa verensin. Senin şifandan başka şifa yoktur; öyle bir şifa ver ki hiçbir hastalık bırakmasın.", "Allah''ım! Mutluluğumuzu ve yuvamızı koru, aramızda anlayış ve hoşnutluk nasip et."]}, "bn": {"title": "আমার স্ত্রীর জন্য দোয়া", "duas": ["হে আমাদের প্রতিপালক! আমাদের স্ত্রী ও সন্তানদের পক্ষ থেকে আমাদের চোখ জুড়ানো প্রশান্তি দান করুন এবং আমাদেরকে মুত্তাকীদের জন্য আদর্শ বানান।", "হে আল্লাহ, আমাদের দুই হৃদয়ের মাঝে মিল সৃষ্টি করুন, এবং আমাদের মাঝে স্থায়ী ভালোবাসা ও রহমত স্থাপন করুন।", "হে আল্লাহ, তাকে আমার চোখের প্রশান্তি বানান, এবং তার জন্য আমাকে সর্বোত্তম সঙ্গী হতে সাহায্য করুন।", "হে আল্লাহ, মানুষের প্রতিপালক! কষ্ট দূর করুন, আরোগ্য দান করুন, আপনিই আরোগ্যদাতা; আপনার আরোগ্য ছাড়া কোনো আরোগ্য নেই—এমন আরোগ্য যা কোনো রোগ অবশিষ্ট রাখে না।", "হে আল্লাহ, আমাদের সুখ ও সংসার হেফাজত করুন, এবং আমাদের মাঝে পারস্পরিক বোঝাপড়া ও সন্তুষ্টি দান করুন।"]}, "ha": {"title": "Addu''ata Ga Matata", "duas": ["Ya Ubangijinmu, ka ba mu abin farin ciki daga matanmu da zuriyarmu, kuma ka sanya mu shugabanni ga masu tsoron Allah.", "Ya Allah, ka hada zukatanmu, kuma ka sanya soyayya da rahama madawwama a tsakaninmu.", "Ya Allah, ka sanya ta abin farin cikin idanuna, kuma ka taimake ni in zama mafi kyawon aboki a gare ta.", "Ya Allah, Ubangijin mutane, ka kawar da cutar, ka warkar da ita, Kai ne Mai warkarwa, babu warkarwa sai warkarwarka, warkarwa da ba ta barin wata cuta.", "Ya Allah, ka tsare farin cikinmu da gidanmu, kuma ka azurta mu da fahimtar juna da yarda a tsakaninmu."]}}}, {"id": "children", "title": "دعائي لأولادي", "icon": "🧒", "duas": ["رب هب لي من الصالحين", "رب اجعلني مقيم الصلاة ومن ذريتي ربنا وتقبل دعاء", "ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إماما", "أعيذكما بكلمات الله التامة من كل شيطان وهامة، ومن كل عين لامّة", "اللهم اجعلهم من الهداة المهتدين، غير الضالين ولا المضلين", "اللهم بارك لي في أولادي ولا تسلبني إياهم، وأرني فيهم قرة عيني قبل موتي", "اللهم اجعلهم قرة عين لي في الدنيا والآخرة، ووفقهم لما تحب وترضى"], "translations": {"en": {"title": "My Dua for My Children", "duas": ["My Lord, grant me a child from among the righteous.", "My Lord, make me an establisher of prayer, and [many] from my descendants. Our Lord, and accept my supplication.", "Our Lord, grant us from among our spouses and offspring comfort to our eyes and make us leaders for the righteous.", "I seek refuge for you both in the perfect words of Allah from every devil and poisonous pest, and from every evil, harmful eye.", "O Allah, make them guides who are rightly guided, neither astray nor leading others astray.", "O Allah, bless me in my children and do not take them from me, and let me see comfort in them before I die.", "O Allah, make them a comfort to my eyes in this world and the Hereafter, and grant them success in what You love and are pleased with."]}, "fr": {"title": "Ma prière pour mes enfants", "duas": ["Seigneur, accorde-moi un enfant du nombre des vertueux.", "Seigneur, fais que j''accomplisse assidûment la prière, ainsi qu''une partie de ma descendance. Notre Seigneur, exauce ma prière.", "Notre Seigneur, accorde-nous, de nos épouses et de nos descendants, la fraîcheur des yeux, et fais de nous un modèle pour les pieux.", "Je vous confie tous deux à la protection des paroles parfaites d''Allah contre tout démon, toute créature venimeuse et tout œil malveillant.", "Ô Allah, fais d''eux des guides bien guidés, ni égarés ni égarant autrui.", "Ô Allah, bénis-moi en mes enfants, ne me les enlève pas, et fais-moi voir en eux la fraîcheur de mes yeux avant ma mort.", "Ô Allah, fais d''eux une fraîcheur pour mes yeux ici-bas et dans l''au-delà, et accorde-leur la réussite dans ce que Tu aimes et agrées."]}, "ur": {"title": "میری دعا اپنی اولاد کے لیے", "duas": ["اے میرے رب! مجھے نیک اولاد عطا فرما۔", "اے میرے رب! مجھے نماز قائم کرنے والا بنا اور میری اولاد میں سے بھی، اے ہمارے رب! میری دعا قبول فرما۔", "اے ہمارے رب! ہمیں اپنی بیویوں اور اولاد سے آنکھوں کی ٹھنڈک عطا فرما، اور ہمیں پرہیزگاروں کا امام بنا۔", "میں تم دونوں کو اللہ کے کامل کلمات کی پناہ میں دیتا ہوں، ہر شیطان اور زہریلے جانور سے، اور ہر نظرِ بد سے۔", "اے اللہ! انہیں ایسا ہدایت یافتہ اور ہدایت دینے والا بنا جو نہ خود گمراہ ہوں اور نہ کسی کو گمراہ کریں۔", "اے اللہ! میری اولاد میں برکت عطا فرما اور مجھے ان سے محروم نہ فرما، اور میری وفات سے پہلے مجھے ان کی وجہ سے آنکھوں کی ٹھنڈک دکھا۔", "اے اللہ! انہیں دنیا اور آخرت میں میری آنکھوں کی ٹھنڈک بنا، اور انہیں ان کاموں کی توفیق دے جو تجھے پسند اور محبوب ہیں۔"]}, "id": {"title": "Doaku untuk Anak-anakku", "duas": ["Ya Tuhanku, anugerahkanlah kepadaku seorang anak yang termasuk orang-orang yang saleh.", "Ya Tuhanku, jadikanlah aku dan anak cucuku orang yang tetap mendirikan salat. Ya Tuhan kami, perkenankanlah doaku.", "Ya Tuhan kami, anugerahkanlah kepada kami pasangan kami dan keturunan kami sebagai penyenang hati, dan jadikanlah kami pemimpin bagi orang-orang yang bertakwa.", "Aku memohonkan perlindungan untuk kalian berdua dengan kalimat-kalimat Allah yang sempurna dari setiap setan dan binatang berbisa, serta dari setiap pandangan mata yang jahat.", "Ya Allah, jadikanlah mereka pemberi petunjuk yang mendapat petunjuk, bukan orang-orang yang sesat maupun yang menyesatkan.", "Ya Allah, berkahilah aku pada anak-anakku dan jangan Engkau cabut mereka dariku, dan perlihatkanlah kepadaku kebahagiaan pada diri mereka sebelum aku wafat.", "Ya Allah, jadikanlah mereka penyejuk mataku di dunia dan akhirat, dan berilah mereka taufik kepada apa yang Engkau cintai dan ridai."]}, "ms": {"title": "Doaku untuk Anak-Anakku", "duas": ["Wahai Tuhanku, kurniakanlah kepadaku seorang anak yang soleh.", "Wahai Tuhanku, jadikanlah aku dan zuriat keturunanku orang yang mendirikan solat. Wahai Tuhan kami, perkenankanlah doaku.", "Wahai Tuhan kami, kurniakanlah kepada kami pasangan dan zuriat kami sebagai penyejuk mata, dan jadikanlah kami imam bagi orang-orang yang bertakwa.", "Aku memohon perlindungan untuk kamu berdua dengan kalimat-kalimat Allah yang sempurna daripada setiap syaitan dan binatang berbisa, dan daripada setiap pandangan mata yang jahat.", "Ya Allah, jadikanlah mereka pemberi petunjuk yang mendapat petunjuk, tidak sesat dan tidak pula menyesatkan orang lain.", "Ya Allah, berkatilah aku pada anak-anakku dan janganlah Engkau mengambil mereka daripadaku, serta perlihatkanlah kepadaku penyejuk mata daripada mereka sebelum aku wafat.", "Ya Allah, jadikanlah mereka penyejuk mataku di dunia dan akhirat, serta kurniakanlah mereka taufik kepada apa yang Engkau cintai dan redai."]}, "hi": {"title": "अपने बच्चों के लिए मेरी दुआ", "duas": ["ऐ मेरे रब! मुझे नेक औलाद अता कर।", "मेरे रब! मुझे नमाज़ क़ायम करने वाला बना, और मेरी औलाद में से भी। ऐ हमारे रब! और मेरी दुआ क़बूल फ़रमा।", "ऐ हमारे रब! हमें अपनी बीवियों और औलाद की तरफ़ से आँखों की ठंडक अता कर, और हमें परहेज़गारों का इमाम बना।", "मैं तुम दोनों को अल्लाह के मुकम्मल कलिमात की पनाह में देता हूँ, हर शैतान और ज़हरीले जानवर से, और हर बुरी नज़र लगाने वाली नज़र से।", "हे अल्लाह! उन्हें ऐसे हिदायत देने वाले बना जो ख़ुद हिदायत-याफ़्ता हों, न ख़ुद गुमराह हों और न दूसरों को गुमराह करें।", "हे अल्लाह! मेरी औलाद में मेरे लिए बरकत रख और उन्हें मुझसे जुदा न कर, और मेरी मौत से पहले मुझे उनमें आँखों की ठंडक दिखा।", "हे अल्लाह! उन्हें दुनिया और आख़िरत में मेरी आँखों की ठंडक बना, और उन्हें उस चीज़ की तौफ़ीक़ दे जिसे तू पसंद करता है और जिससे तू राज़ी होता है।"]}, "tr": {"title": "Çocuklarım İçin Duam", "duas": ["Rabbim! Bana salihlerden olacak bir evlat bağışla.", "Rabbim! Beni namazı devamlı kılan biri eyle, soyumdan da böyle kimseler yarat. Rabbimiz! Duamı kabul buyur.", "Rabbimiz! Eşlerimizi ve çocuklarımızı bize göz aydınlığı kıl ve bizi takva sahiplerine önder eyle.", "Sizi Allah''ın eksiksiz kelimeleriyle her şeytandan, zararlı haşereden ve nazar değen her gözden korurum.", "Allah''ım! Onları hidayete eren ve başkalarını da hidayete erdiren kimselerden eyle; sapmayan ve saptırmayan kimselerden kıl.", "Allah''ım! Çocuklarımı benim için bereketli kıl, onları benden alma ve ölmeden önce onlarda göz aydınlığımı göster.", "Allah''ım! Onları dünyada ve ahirette bana göz aydınlığı kıl, sevdiğin ve razı olduğun şeylere onları muvaffak eyle."]}, "bn": {"title": "আমার সন্তানদের জন্য দোয়া", "duas": ["হে আমার প্রতিপালক! আমাকে সৎকর্মশীল সন্তান দান করুন।", "হে আমার প্রতিপালক! আমাকে নামাজ প্রতিষ্ঠাকারী বানান, এবং আমার বংশধরদের থেকেও। হে আমাদের প্রতিপালক! আমার দোয়া কবুল করুন।", "হে আমাদের প্রতিপালক! আমাদের স্ত্রী ও সন্তানদের পক্ষ থেকে আমাদের চোখ জুড়ানো প্রশান্তি দান করুন এবং আমাদেরকে মুত্তাকীদের জন্য আদর্শ বানান।", "আমি তোমাদের উভয়কে আল্লাহর পরিপূর্ণ কালিমাসমূহের আশ্রয়ে দিচ্ছি প্রত্যেক শয়তান ও বিষাক্ত প্রাণী থেকে, এবং প্রত্যেক অনিষ্টকর কুদৃষ্টি থেকে।", "হে আল্লাহ, তাদেরকে হিদায়াতপ্রাপ্ত পথপ্রদর্শক বানান, যারা নিজেরা পথভ্রষ্ট হবে না, আর অন্যকেও পথভ্রষ্ট করবে না।", "হে আল্লাহ, আমার সন্তানদের মধ্যে বরকত দিন এবং তাদেরকে আমার কাছ থেকে ছিনিয়ে নেবেন না, আমার মৃত্যুর আগে তাদের মধ্যে আমার চোখের প্রশান্তি দেখিয়ে দিন।", "হে আল্লাহ, তাদেরকে দুনিয়া ও আখিরাতে আমার চোখের প্রশান্তি বানান, এবং আপনি যা পছন্দ করেন ও যাতে সন্তুষ্ট হন সেই কাজের তাওফিক তাদের দিন।"]}, "ha": {"title": "Addu''ata Ga ''Ya''yana", "duas": ["Ya Ubangijina, ka ba ni daga cikin salihai.", "Ya Ubangijina, ka sanya ni mai tsayar da sallah, haka kuma daga zuriyata. Ya Ubangijinmu, kuma ka karbi addu''ata.", "Ya Ubangijinmu, ka ba mu abin farin ciki daga matanmu da zuriyarmu, kuma ka sanya mu shugabanni ga masu tsoron Allah.", "Ina neman tsari a gare ku biyu da cikakkun kalmomin Allah daga kowane shaidan da dabba mai dafi, da kuma daga kowace mummunar ido.", "Ya Allah, ka sanya su daga cikin masu shiryarwa wadanda aka shiryar, ba batattu ba kuma ba masu batar da wasu ba.", "Ya Allah, ka sanya albarka a cikin ''ya''yana kuma kada Ka karbe su daga gare ni, ka nuna mini farin cikina a cikinsu kafin in rasu.", "Ya Allah, ka sanya su abin farin cikin idanuna a duniya da lahira, kuma ka ba su ikon yin abin da Kake so kuma kake yarda da shi."]}}}, {"id": "mother", "title": "دعائي لأمي", "icon": "🤱", "duas": ["رب ارحمهما كما ربياني صغيرا", "ربنا اغفر لي ولوالديّ وللمؤمنين يوم يقوم الحساب", "اللهم أطل عمرها على طاعتك، وارزقها الصحة والعافية", "اللهم اغفر لها ذنوبها، وارفع درجتها، وأكرم نزلها", "اللهم اجعل الفردوس الأعلى مثواها، وأثبها عني خير الجزاء"], "translations": {"en": {"title": "My Dua for My Mother", "duas": ["My Lord, have mercy upon them as they brought me up when I was small.", "Our Lord, forgive me and my parents and the believers the Day the account is established.", "O Allah, prolong her life in obedience to You, and grant her health and wellbeing.", "O Allah, forgive her sins, raise her rank, and honor her abode.", "O Allah, make the highest Paradise her dwelling, and reward her on my behalf with the best of rewards."]}, "fr": {"title": "Ma prière pour ma mère", "duas": ["Seigneur, fais-leur, à tous deux, miséricorde comme ils m''ont élevé tout petit.", "Notre Seigneur, pardonne-moi, ainsi qu''à mes parents et aux croyants, le jour où se dressera le compte.", "Ô Allah, prolonge sa vie dans Ton obéissance, et accorde-lui la santé et le bien-être.", "Ô Allah, pardonne-lui ses péchés, élève son rang, et honore sa demeure.", "Ô Allah, fais du plus haut Paradis sa demeure, et récompense-la de ma part par la meilleure des récompenses."]}, "ur": {"title": "میری دعا اپنی والدہ کے لیے", "duas": ["اے میرے رب! ان دونوں پر رحم فرما جس طرح انہوں نے بچپن میں میری پرورش کی۔", "اے ہمارے رب! مجھے، میرے والدین کو اور تمام مومنوں کو اس دن بخش دے جس دن حساب قائم ہوگا۔", "اے اللہ! اس کی عمر اپنی اطاعت میں دراز فرما، اور اسے صحت و عافیت عطا فرما۔", "اے اللہ! اس کے گناہ بخش دے، اس کا درجہ بلند فرما، اور اس کی قیام گاہ کو باعزت بنا۔", "اے اللہ! جنت الفردوس کو اس کا ٹھکانہ بنا، اور میری طرف سے اسے بہترین جزا عطا فرما۔"]}, "id": {"title": "Doaku untuk Ibuku", "duas": ["Ya Tuhanku, sayangilah keduanya sebagaimana mereka berdua telah mendidikku pada waktu kecil.", "Ya Tuhan kami, ampunilah aku dan kedua orang tuaku serta semua orang yang beriman pada hari terjadinya hisab (hari kiamat).", "Ya Allah, panjangkanlah umurnya dalam ketaatan kepada-Mu, dan karuniakanlah kepadanya kesehatan dan keselamatan.", "Ya Allah, ampunilah dosa-dosanya, angkatlah derajatnya, dan muliakanlah tempat tinggalnya.", "Ya Allah, jadikanlah surga Firdaus yang tertinggi sebagai tempat tinggalnya, dan balaslah kebaikannya untukku dengan sebaik-baik balasan."]}, "ms": {"title": "Doaku untuk Ibuku", "duas": ["Wahai Tuhanku, kasihanilah kedua-duanya sebagaimana mereka mendidikku sewaktu kecil.", "Wahai Tuhan kami, ampunkanlah aku, kedua ibu bapaku, dan sekalian orang beriman pada hari hisab (perhitungan) ditegakkan.", "Ya Allah, panjangkanlah umurnya dalam ketaatan kepada-Mu, dan kurniakanlah kesihatan serta kesejahteraan kepadanya.", "Ya Allah, ampunilah dosa-dosanya, tinggikanlah darjatnya, dan muliakanlah tempat kembalinya.", "Ya Allah, jadikanlah syurga Firdaus yang tertinggi sebagai tempat tinggalnya, dan balaslah jasanya bagi pihakku dengan sebaik-baik balasan."]}, "hi": {"title": "अपनी माँ के लिए मेरी दुआ", "duas": ["मेरे रब! उन दोनों पर रहम फ़रमा, जैसे उन्होंने बचपन में मेरी परवरिश की।", "ऐ हमारे रब! मुझे, मेरे माता-पिता को और मोमिनों को उस दिन बख़्श दे जिस दिन हिसाब क़ायम होगा।", "हे अल्लाह! उसकी उम्र तेरी इताअत में लंबी कर, और उसे सेहत और आफ़ियत अता कर।", "हे अल्लाह! उसके गुनाह बख़्श दे, उसका दर्जा बुलंद कर, और उसकी मंज़िल को इज़्ज़त वाला बना।", "हे अल्लाह! उसका ठिकाना फ़िरदौस के सबसे ऊँचे दर्जे में बना, और मेरी तरफ़ से उसे बेहतरीन बदला दे।"]}, "tr": {"title": "Annem İçin Duam", "duas": ["Rabbim, onlar beni küçükken yetiştirdikleri gibi, sen de onlara merhamet eyle.", "Rabbimiz! Hesabın görüleceği gün beni, anne babamı ve müminleri bağışla.", "Allah''ım! Onun ömrünü sana itaat üzere uzun eyle, ona sağlık ve afiyet ver.", "Allah''ım! Onun günahlarını bağışla, derecesini yükselt, konaklama yerini şerefli kıl.", "Allah''ım! Firdevs-i A''lâ''yı onun makamı kıl ve onu benim adıma en güzel karşılıkla mükâfatlandır."]}, "bn": {"title": "আমার মায়ের জন্য দোয়া", "duas": ["হে আমার প্রতিপালক! আপনি তাদের প্রতি দয়া করুন, যেভাবে তারা শৈশবে আমাকে লালন-পালন করেছেন।", "হে আমাদের প্রতিপালক! আপনি আমাকে, আমার পিতা-মাতাকে এবং মুমিনদেরকে ক্ষমা করুন, যেদিন হিসাব সংঘটিত হবে।", "হে আল্লাহ, তার হায়াতকে আপনার আনুগত্যে দীর্ঘায়িত করুন, এবং তাকে সুস্থতা ও নিরাপত্তা দান করুন।", "হে আল্লাহ, তার গুনাহ ক্ষমা করুন, তার মর্যাদা উঁচু করুন এবং তার আবাসস্থলকে সম্মানিত করুন।", "হে আল্লাহ, জান্নাতের সর্বোচ্চ স্তর ফিরদাউসকে তার আবাসস্থল বানান, এবং আমার পক্ষ থেকে তাকে সর্বোত্তম প্রতিদান দিন।"]}, "ha": {"title": "Addu''ata Ga Mahaifiyata", "duas": ["Ya Ubangijina, ka yi musu rahama kamar yadda suka rene ni tun ina karama.", "Ya Ubangijinmu, ka gafarta mini da iyayena da kuma muminai a ranar da za a tsayar da hisabi.", "Ya Allah, ka tsawaita rayuwarta a kan yin biyayya gare ka, kuma ka azurta ta da lafiya da koshin lafiya.", "Ya Allah, ka gafarta mata zunubanta, ka daukaka darajarta, kuma ka girmama masaukinta.", "Ya Allah, ka sanya Firdausi mafi daukaka ya zama mazauninta, kuma ka ba ta sakayya mafi kyau daga gare ni."]}}}, {"id": "father", "title": "دعائي لأبي", "icon": "🧔", "duas": ["رب ارحمهما كما ربياني صغيرا", "ربنا اغفر لي ولوالديّ وللمؤمنين يوم يقوم الحساب", "اللهم ارزقه القوة والعافية، وبارك له في عمره وعمله", "اللهم سدّد خطاه، وأعنه على أمور دينه ودنياه", "اللهم اجزه عني خير ما جزيت والدًا عن ولده"], "translations": {"en": {"title": "My Dua for My Father", "duas": ["My Lord, have mercy upon them as they brought me up when I was small.", "Our Lord, forgive me and my parents and the believers the Day the account is established.", "O Allah, grant him strength and wellbeing, and bless his life and his work.", "O Allah, guide his steps rightly, and help him in the matters of his religion and his worldly life.", "O Allah, reward him on my behalf with the best reward You have ever given a parent from a child."]}, "fr": {"title": "Ma prière pour mon père", "duas": ["Seigneur, fais-leur, à tous deux, miséricorde comme ils m''ont élevé tout petit.", "Notre Seigneur, pardonne-moi, ainsi qu''à mes parents et aux croyants, le jour où se dressera le compte.", "Ô Allah, accorde-lui la force et le bien-être, et bénis sa vie et son travail.", "Ô Allah, guide ses pas avec droiture, et aide-le dans les affaires de sa religion et de sa vie d''ici-bas.", "Ô Allah, récompense-le de ma part par la meilleure récompense que Tu aies jamais accordée à un parent de la part de son enfant."]}, "ur": {"title": "میری دعا اپنے والد کے لیے", "duas": ["اے میرے رب! ان دونوں پر رحم فرما جس طرح انہوں نے بچپن میں میری پرورش کی۔", "اے ہمارے رب! مجھے، میرے والدین کو اور تمام مومنوں کو اس دن بخش دے جس دن حساب قائم ہوگا۔", "اے اللہ! اسے قوت اور عافیت عطا فرما، اور اس کی عمر اور اس کے کام میں برکت عطا فرما۔", "اے اللہ! اس کے قدموں کو راہِ راست پر رکھ، اور اس کے دینی و دنیاوی معاملات میں اس کی مدد فرما۔", "اے اللہ! اسے میری طرف سے وہ بہترین جزا عطا فرما جو تو نے کسی والد کو اس کی اولاد کی طرف سے دی ہو۔"]}, "id": {"title": "Doaku untuk Ayahku", "duas": ["Ya Tuhanku, sayangilah keduanya sebagaimana mereka berdua telah mendidikku pada waktu kecil.", "Ya Tuhan kami, ampunilah aku dan kedua orang tuaku serta semua orang yang beriman pada hari terjadinya hisab (hari kiamat).", "Ya Allah, karuniakanlah kepadanya kekuatan dan keselamatan, dan berkahilah umur dan pekerjaannya.", "Ya Allah, luruskanlah langkahnya, dan bantulah dia dalam urusan agama dan dunianya.", "Ya Allah, balaslah kebaikannya untukku dengan sebaik-baik balasan yang pernah Engkau berikan kepada orang tua dari anaknya."]}, "ms": {"title": "Doaku untuk Ayahku", "duas": ["Wahai Tuhanku, kasihanilah kedua-duanya sebagaimana mereka mendidikku sewaktu kecil.", "Wahai Tuhan kami, ampunkanlah aku, kedua ibu bapaku, dan sekalian orang beriman pada hari hisab (perhitungan) ditegakkan.", "Ya Allah, kurniakanlah kepadanya kekuatan dan kesejahteraan, serta berkatilah umur dan pekerjaannya.", "Ya Allah, teguhkanlah langkahnya, dan bantulah dia dalam urusan agama dan dunianya.", "Ya Allah, balaslah jasanya bagi pihakku dengan sebaik-baik balasan yang pernah Engkau berikan kepada seorang ibu bapa daripada anaknya."]}, "hi": {"title": "अपने पिता के लिए मेरी दुआ", "duas": ["मेरे रब! उन दोनों पर रहम फ़रमा, जैसे उन्होंने बचपन में मेरी परवरिश की।", "ऐ हमारे रब! मुझे, मेरे माता-पिता को और मोमिनों को उस दिन बख़्श दे जिस दिन हिसाब क़ायम होगा।", "हे अल्लाह! उसे ताक़त और आफ़ियत अता कर, और उसकी उम्र और उसके काम में बरकत दे।", "हे अल्लाह! उसके क़दम जमाए रख, और उसके दीन और दुनिया के मामलों में उसकी मदद फ़रमा।", "हे अल्लाह! मेरी तरफ़ से उसे वह बेहतरीन बदला दे जो तूने किसी वालिद को अपनी औलाद से दिया हो।"]}, "tr": {"title": "Babam İçin Duam", "duas": ["Rabbim, onlar beni küçükken yetiştirdikleri gibi, sen de onlara merhamet eyle.", "Rabbimiz! Hesabın görüleceği gün beni, anne babamı ve müminleri bağışla.", "Allah''ım! Ona güç ve afiyet ver, ömrünü ve işini bereketli kıl.", "Allah''ım! Adımlarını doğrult, din ve dünya işlerinde ona yardım et.", "Allah''ım! Bir babaya evladından verilebilecek en hayırlı karşılığı ona benden ver."]}, "bn": {"title": "আমার বাবার জন্য দোয়া", "duas": ["হে আমার প্রতিপালক! আপনি তাদের প্রতি দয়া করুন, যেভাবে তারা শৈশবে আমাকে লালন-পালন করেছেন।", "হে আমাদের প্রতিপালক! আপনি আমাকে, আমার পিতা-মাতাকে এবং মুমিনদেরকে ক্ষমা করুন, যেদিন হিসাব সংঘটিত হবে।", "হে আল্লাহ, তাকে শক্তি ও সুস্থতা দান করুন, এবং তার জীবন ও কর্মে বরকত দিন।", "হে আল্লাহ, তার পদক্ষেপকে দৃঢ় ও সঠিক পথে পরিচালিত করুন, এবং তার দ্বীন ও দুনিয়ার বিষয়ে তাকে সাহায্য করুন।", "হে আল্লাহ, আমার পক্ষ থেকে তাকে এমন উত্তম প্রতিদান দিন, যা আপনি কোনো পিতাকে তার সন্তানের পক্ষ থেকে দিয়েছেন তার চেয়েও উত্তম।"]}, "ha": {"title": "Addu''ata Ga Mahaifina", "duas": ["Ya Ubangijina, ka yi musu rahama kamar yadda suka rene ni tun ina karama.", "Ya Ubangijinmu, ka gafarta mini da iyayena da kuma muminai a ranar da za a tsayar da hisabi.", "Ya Allah, ka azurta shi da karfi da koshin lafiya, kuma ka sanya albarka a rayuwarsa da aikinsa.", "Ya Allah, ka daidaita matakansa, kuma ka taimake shi a al''amuran addininsa da duniyarsa.", "Ya Allah, ka saka masa sakayya mafi kyau da Ka taba saka wa iyaye daga yaransu."]}}}, {"id": "family", "title": "دعائي للأهل والأقارب", "icon": "🏡", "duas": ["رب اغفر لي ولوالديّ ولمن دخل بيتي مؤمنا وللمؤمنين والمؤمنات", "اللهم صِل من وصلني منهم، واجعلني سببًا في تآلف قلوبهم واجتماع شملهم", "اللهم اشفِ مريضهم، وفرّج همّهم، وارزقهم من فضلك ما يغنيهم"], "translations": {"en": {"title": "My Dua for Family and Relatives", "duas": ["My Lord, forgive me and my parents and whoever enters my house a believer, and the believing men and believing women.", "O Allah, maintain ties with those among them who maintain ties with me, and make me a means of uniting their hearts and gathering them together.", "O Allah, heal their sick, relieve their distress, and grant them from Your bounty what suffices them."]}, "fr": {"title": "Ma prière pour ma famille et mes proches", "duas": ["Seigneur, pardonne-moi, ainsi qu''à mes parents, à quiconque entre dans ma maison en croyant, et aux croyants et aux croyantes.", "Ô Allah, garde le lien avec ceux d''entre eux qui gardent le lien avec moi, et fais de moi une cause d''union de leurs cœurs et de rassemblement entre eux.", "Ô Allah, guéris leurs malades, dissipe leurs soucis, et accorde-leur de Ta grâce de quoi les rendre indépendants du besoin."]}, "ur": {"title": "میری دعا اہلِ خانہ اور رشتہ داروں کے لیے", "duas": ["اے میرے رب! مجھے، میرے والدین کو، اور جو کوئی مومن ہو کر میرے گھر میں داخل ہو اسے، اور تمام مومن مردوں اور عورتوں کو بخش دے۔", "اے اللہ! ان میں سے جو مجھ سے صلہ رحمی کرے اس سے صلہ رحمی فرما، اور مجھے ان کے دلوں کو جوڑنے اور انہیں متحد کرنے کا ذریعہ بنا۔", "اے اللہ! ان کے بیماروں کو شفا عطا فرما، ان کی پریشانیاں دور فرما، اور اپنے فضل سے انہیں اتنا عطا فرما جو ان کے لیے کافی ہو۔"]}, "id": {"title": "Doaku untuk Keluarga dan Kerabat", "duas": ["Ya Tuhanku, ampunilah aku, kedua orang tuaku, dan siapa saja yang memasuki rumahku dalam keadaan beriman, serta orang-orang mukmin laki-laki dan perempuan.", "Ya Allah, sambungkanlah tali silaturahmi dengan orang yang menyambungkannya denganku di antara mereka, dan jadikanlah aku sebab bersatunya hati mereka dan berkumpulnya mereka.", "Ya Allah, sembuhkanlah orang yang sakit di antara mereka, lapangkanlah kesusahan mereka, dan karuniakanlah kepada mereka dari karunia-Mu apa yang mencukupi mereka."]}, "ms": {"title": "Doaku untuk Keluarga dan Kaum Kerabat", "duas": ["Wahai Tuhanku, ampunkanlah aku, kedua ibu bapaku, dan sesiapa yang memasuki rumahku dalam keadaan beriman, serta sekalian orang-orang mukmin lelaki dan perempuan.", "Ya Allah, eratkanlah hubungan silaturahim dengan mereka yang menghubungkan silaturahim denganku, dan jadikanlah aku punca kepada bersatunya hati mereka dan berhimpunnya mereka.", "Ya Allah, sembuhkanlah yang sakit di kalangan mereka, hilangkanlah kesusahan mereka, dan kurniakanlah mereka daripada limpah kurnia-Mu apa yang mencukupi mereka."]}, "hi": {"title": "परिवार और रिश्तेदारों के लिए मेरी दुआ", "duas": ["मेरे रब! मुझे, मेरे माता-पिता को और जो भी मोमिन बनकर मेरे घर में दाख़िल हो उसे, और तमाम मोमिन मर्दों-औरतों को बख़्श दे।", "हे अल्लाह! जो मुझसे रिश्ता जोड़े उससे तू भी रिश्ता जोड़, और मुझे उनके दिलों की उल्फ़त और उनकी एकजुटता का सबब बना।", "हे अल्लाह! उनके बीमारों को शिफ़ा दे, उनकी परेशानी दूर कर, और अपने फ़ज़ल से उन्हें इतना दे जो उन्हें बेनियाज़ कर दे।"]}, "tr": {"title": "Ailem ve Akrabalarım İçin Duam", "duas": ["Rabbim! Beni, anne babamı, evime mümin olarak giren kimseyi, mümin erkekleri ve mümin kadınları bağışla.", "Allah''ım! Onlardan bana akrabalık bağını gözetenlerle ilgimi sürdür, kalplerinin kaynaşmasına ve aralarının birleşmesine beni vesile kıl.", "Allah''ım! Hastalarına şifa ver, sıkıntılarını gider, onlara lütfundan yetecekleri kadar rızık ver."]}, "bn": {"title": "আমার পরিবার ও আত্মীয়স্বজনের জন্য দোয়া", "duas": ["হে আমার প্রতিপালক! আমাকে, আমার পিতা-মাতাকে এবং যে মুমিন হয়ে আমার ঘরে প্রবেশ করে তাকে ক্ষমা করুন, এবং মুমিন নারী-পুরুষদেরকেও ক্ষমা করুন।", "হে আল্লাহ, তাদের মধ্যে যারা আমার সাথে সম্পর্ক বজায় রাখে তাদের সাথে সম্পর্ক বজায় রাখুন, এবং আমাকে তাদের হৃদয়ের মিলন ও তাদের একত্রীকরণের উপলক্ষ বানান।", "হে আল্লাহ, তাদের অসুস্থদের আরোগ্য দান করুন, তাদের দুশ্চিন্তা দূর করুন, এবং আপনার অনুগ্রহ থেকে তাদেরকে এমন কিছু দান করুন যা তাদের জন্য যথেষ্ট হয়।"]}, "ha": {"title": "Addu''ata Ga Iyali Da ''Yan Uwa", "duas": ["Ya Ubangijina, ka gafarta mini da iyayena da duk wanda ya shiga gidana yana mumini, da kuma muminai maza da mata.", "Ya Allah, ka sadar da wanda ya sadu da ni daga cikinsu, kuma ka sanya ni dalilin hadewar zukatansu da tarayyar su.", "Ya Allah, ka warkar da majinyatansu, ka kawar musu da damuwarsu, kuma ka azurta su daga falalarka da abin da zai wadatar da su."]}}}, {"id": "friends", "title": "دعائي للأصدقاء والأحبة", "icon": "🤝", "duas": ["اللهم اجزهم عني خيرًا على كل معروف قدّموه لي", "اللهم بارك لهم فيما رزقتهم، واجمعنا وإياهم في مقعد صدق عندك", "اللهم أدم بيننا المحبة والوفاء، واجعلنا عونًا لبعضنا على الخير"], "translations": {"en": {"title": "My Dua for Friends and Loved Ones", "duas": ["O Allah, reward them on my behalf with good for every kindness they have shown me.", "O Allah, bless them in what You have provided them, and gather us together with them in a seat of truth in Your presence.", "O Allah, make our love and loyalty lasting, and make us a support for one another in good."]}, "fr": {"title": "Ma prière pour mes amis et mes proches", "duas": ["Ô Allah, récompense-les de ma part par le bien pour chaque bienfait qu''ils m''ont rendu.", "Ô Allah, bénis-les dans ce que Tu leur as accordé, et réunis-nous avec eux dans un séjour de vérité auprès de Toi.", "Ô Allah, fais durer entre nous l''affection et la loyauté, et fais de nous un soutien les uns pour les autres dans le bien."]}, "ur": {"title": "میری دعا دوستوں اور پیاروں کے لیے", "duas": ["اے اللہ! انہوں نے مجھ پر جو بھی احسان کیا اس پر انہیں میری طرف سے بہترین جزا عطا فرما۔", "اے اللہ! جو کچھ تو نے انہیں عطا کیا ہے اس میں برکت دے، اور ہمیں اور انہیں اپنے حضور سچائی کے مقام میں جمع فرما۔", "اے اللہ! ہمارے درمیان محبت اور وفا ہمیشہ قائم رکھ، اور ہمیں نیکی کے کاموں میں ایک دوسرے کا مددگار بنا۔"]}, "id": {"title": "Doaku untuk Sahabat dan Orang-orang Tercinta", "duas": ["Ya Allah, balaslah kebaikan mereka untukku atas setiap kebaikan yang telah mereka berikan kepadaku.", "Ya Allah, berkahilah mereka pada rezeki yang telah Engkau berikan, dan kumpulkanlah kami bersama mereka di tempat yang benar di sisi-Mu.", "Ya Allah, langgengkanlah cinta dan kesetiaan di antara kami, dan jadikanlah kami saling menolong dalam kebaikan."]}, "ms": {"title": "Doaku untuk Sahabat dan Orang Tersayang", "duas": ["Ya Allah, balaslah mereka bagi pihakku dengan kebaikan atas setiap kebaikan yang telah mereka berikan kepadaku.", "Ya Allah, berkatilah mereka pada rezeki yang telah Engkau kurniakan, dan kumpulkanlah kami bersama mereka di tempat yang benar di sisi-Mu.", "Ya Allah, kekalkanlah kasih sayang dan kesetiaan antara kami, dan jadikanlah kami saling membantu dalam kebaikan."]}, "hi": {"title": "दोस्तों और प्रियजनों के लिए मेरी दुआ", "duas": ["हे अल्लाह! उन्होंने मुझ पर जो भी एहसान किए हैं, उन सबका मेरी तरफ़ से उन्हें बेहतरीन बदला दे।", "हे अल्लाह! जो कुछ तूने उन्हें दिया है उसमें बरकत दे, और हमें और उन्हें अपने पास सच्चाई की जगह पर इकट्ठा कर।", "हे अल्लाह! हमारे बीच मोहब्बत और वफ़ादारी हमेशा क़ायम रख, और हमें एक-दूसरे की भलाई में मददगार बना।"]}, "tr": {"title": "Arkadaşlarım ve Sevdiklerim İçin Duam", "duas": ["Allah''ım! Bana yaptıkları her iyilik karşılığında onlara benim adıma hayırla karşılık ver.", "Allah''ım! Kendilerine verdiğin rızıkta onları bereketlendir, bizi ve onları katındaki doğruluk makamında bir araya getir.", "Allah''ım! Aramızdaki sevgi ve vefayı kalıcı kıl, bizi hayırda birbirimize destek eyle."]}, "bn": {"title": "আমার বন্ধু ও প্রিয়জনদের জন্য দোয়া", "duas": ["হে আল্লাহ, তারা আমার সাথে যে সদাচরণ করেছে তার জন্য আমার পক্ষ থেকে তাদেরকে উত্তম প্রতিদান দিন।", "হে আল্লাহ, আপনি তাদেরকে যা দান করেছেন তাতে বরকত দিন, এবং আমাদেরকে ও তাদেরকে আপনার সান্নিধ্যে সত্যের আসনে একত্র করুন।", "হে আল্লাহ, আমাদের মাঝে ভালোবাসা ও বিশ্বস্ততা স্থায়ী রাখুন, এবং আমাদেরকে কল্যাণের কাজে একে অপরের সহায়ক বানান।"]}, "ha": {"title": "Addu''ata Ga Abokai Da Masoya", "duas": ["Ya Allah, ka saka musu da alheri daga gare ni saboda kowace kyauta da suka yi mini.", "Ya Allah, ka sanya albarka a cikin abin da ka azurta su, kuma ka tara mu tare da su a wurin zama na gaskiya a wurinka.", "Ya Allah, ka dawwamar da soyayya da aminci a tsakaninmu, kuma ka sanya mu taimako ga juna a kan alheri."]}}}, {"id": "ummah", "title": "دعائي لعموم المسلمين والمستضعفين", "icon": "🕋", "duas": ["ربنا أخرجنا من هذه القرية الظالم أهلها واجعل لنا من لدنك وليا واجعل لنا من لدنك نصيرا", "ربنا اغفر لنا ولإخواننا الذين سبقونا بالإيمان ولا تجعل في قلوبنا غلا للذين آمنوا ربنا إنك رءوف رحيم", "اللهم انصر المستضعفين من المسلمين في كل مكان، وفرّج كربهم، واجمع شملهم"], "translations": {"en": {"title": "My Dua for All Muslims and the Oppressed", "duas": ["Our Lord, take us out of this city of oppressive people and appoint for us from Yourself a protector and appoint for us from Yourself a helper.", "Our Lord, forgive us and our brothers who preceded us in faith and put not in our hearts [any] resentment toward those who have believed. Our Lord, indeed You are Kind and Merciful.", "O Allah, grant victory to the oppressed among the Muslims everywhere, relieve their distress, and bring them together."]}, "fr": {"title": "Ma prière pour tous les musulmans et les opprimés", "duas": ["Notre Seigneur, fais-nous sortir de cette cité dont les habitants sont injustes, et accorde-nous, venant de Toi, un protecteur, et accorde-nous, venant de Toi, un secoureur.", "Notre Seigneur, pardonne-nous, ainsi qu''à nos frères qui nous ont précédés dans la foi, et ne mets dans nos cœurs aucune rancune envers ceux qui ont cru. Notre Seigneur, Tu es Compatissant et Miséricordieux.", "Ô Allah, accorde la victoire aux musulmans opprimés où qu''ils soient, dissipe leur détresse, et réunis-les."]}, "ur": {"title": "میری دعا تمام مسلمانوں اور کمزوروں کے لیے", "duas": ["اے ہمارے رب! ہمیں اس بستی سے نکال جس کے باشندے ظالم ہیں، اور اپنی طرف سے ہمارے لیے کوئی حامی مقرر فرما، اور اپنی طرف سے ہمارے لیے کوئی مددگار مقرر فرما۔", "اے ہمارے رب! ہمیں اور ہمارے ان بھائیوں کو بخش دے جو ایمان لانے میں ہم سے پہلے گزر چکے، اور ایمان والوں کے لیے ہمارے دلوں میں کوئی کینہ نہ رکھ، اے ہمارے رب! بیشک تو بہت شفقت کرنے والا، نہایت رحم فرمانے والا ہے۔", "اے اللہ! دنیا بھر کے کمزور مسلمانوں کی مدد فرما، ان کی مصیبتیں دور فرما، اور انہیں متحد فرما۔"]}, "id": {"title": "Doaku untuk Seluruh Kaum Muslimin dan Kaum yang Tertindas", "duas": ["Ya Tuhan kami, keluarkanlah kami dari negeri ini yang penduduknya zalim, berilah kami pelindung dari sisi-Mu, dan berilah kami penolong dari sisi-Mu.", "Ya Tuhan kami, ampunilah kami dan saudara-saudara kami yang telah beriman lebih dahulu dari kami, dan janganlah Engkau tanamkan kedengkian dalam hati kami terhadap orang-orang yang beriman. Ya Tuhan kami, sesungguhnya Engkau Maha Penyantun lagi Maha Penyayang.", "Ya Allah, tolonglah kaum muslimin yang tertindas di setiap tempat, lapangkanlah kesusahan mereka, dan satukanlah mereka."]}, "ms": {"title": "Doaku untuk Umat Islam dan Golongan yang Tertindas", "duas": ["Wahai Tuhan kami, keluarkanlah kami daripada negeri yang zalim penduduknya ini, dan kurniakanlah kepada kami dari sisi-Mu seorang pelindung, serta kurniakanlah kepada kami dari sisi-Mu seorang penolong.", "Wahai Tuhan kami, ampunkanlah kami dan saudara-saudara kami yang telah mendahului kami dalam keimanan, dan janganlah Engkau jadikan dalam hati kami rasa dengki terhadap orang-orang yang beriman. Wahai Tuhan kami, sesungguhnya Engkau Maha Pengasih lagi Maha Penyayang.", "Ya Allah, berikanlah kemenangan kepada golongan yang tertindas di kalangan umat Islam di setiap tempat, hilangkanlah kesusahan mereka, dan satukanlah mereka."]}, "hi": {"title": "सभी मुसलमानों और मज़लूमों के लिए मेरी दुआ", "duas": ["ऐ हमारे रब! हमें इस बस्ती से निकाल दे जिसके बाशिंदे ज़ालिम हैं, और अपनी तरफ़ से हमारे लिए कोई हिमायती बना दे, और अपनी तरफ़ से हमारे लिए कोई मददगार बना दे।", "ऐ हमारे रब! हमें और हमारे उन भाइयों को बख़्श दे जो ईमान में हमसे पहले गुज़रे, और हमारे दिलों में ईमान वालों के लिए कोई कीना न रख। ऐ हमारे रब! बेशक तू बड़ा शफ़ीक़, रहम करने वाला है।", "हे अल्लाह! दुनिया भर के मज़लूम मुसलमानों की मदद फ़रमा, उनकी परेशानी दूर कर, और उन्हें एकजुट कर दे।"]}, "tr": {"title": "Tüm Müslümanlar ve Mustazaflar İçin Duam", "duas": ["Rabbimiz! Bizi halkı zalim olan bu şehirden çıkar, bize katından bir dost ver, bize katından bir yardımcı ver.", "Rabbimiz! Bizi ve bizden önce iman etmiş olan kardeşlerimizi bağışla, kalplerimizde iman edenlere karşı hiçbir kin bırakma. Rabbimiz! Şüphesiz sen çok şefkatli, çok merhametlisin.", "Allah''ım! Her yerdeki mustazaf Müslümanlara yardım et, sıkıntılarını gider, onları bir araya getir."]}, "bn": {"title": "সকল মুসলিম ও নির্যাতিত মানুষের জন্য দোয়া", "duas": ["হে আমাদের প্রতিপালক! আমাদেরকে এই জালিম অধিবাসীদের জনপদ থেকে বের করে নিন, এবং আপনার পক্ষ থেকে আমাদের জন্য একজন অভিভাবক নিযুক্ত করুন, এবং আপনার পক্ষ থেকে আমাদের জন্য একজন সাহায্যকারী নিযুক্ত করুন।", "হে আমাদের প্রতিপালক! আমাদেরকে এবং আমাদের সেই ভাইদেরকে ক্ষমা করুন যারা ঈমান আনয়নে আমাদের অগ্রগামী ছিলেন, এবং যারা ঈমান এনেছে তাদের প্রতি আমাদের অন্তরে কোনো বিদ্বেষ রাখবেন না। হে আমাদের প্রতিপালক! নিশ্চয় আপনি অতি স্নেহশীল, পরম দয়ালু।", "হে আল্লাহ, সর্বত্র নির্যাতিত মুসলিমদেরকে সাহায্য করুন, তাদের দুর্দশা দূর করুন, এবং তাদেরকে একত্র করুন।"]}, "ha": {"title": "Addu''ata Ga Musulmi Baki Daya Da Wadanda Aka Zalunta", "duas": ["Ya Ubangijinmu, ka fitar da mu daga wannan gari wanda mutanensa suke azzalumai, kuma ka sanya mana majibinci daga wurinka, ka sanya mana mataimaki daga wurinka.", "Ya Ubangijinmu, ka gafarta mana da ''yan uwanmu wadanda suka gabace mu da imani, kuma kada Ka sanya a zukatanmu wani kiyayya ga wadanda suka yi imani. Ya Ubangijinmu, lallai Kai Mai tausayi ne Mai jin kai.", "Ya Allah, ka taimaki wadanda aka raunana daga musulmi a ko''ina, ka kawar musu da bakin ciki, kuma ka hada kansu."]}}}, {"id": "reassurance", "title": "الطمأنينة عند الخوف والفزع والقلق", "icon": "🕊️", "duas": ["ربنا أفرغ علينا صبرا وثبت أقدامنا وانصرنا على القوم الكافرين", "ربنا لا تزغ قلوبنا بعد إذ هديتنا وهب لنا من لدنك رحمة إنك أنت الوهاب", "حسبنا الله ونعم الوكيل", "اللهم إني أعوذ بك من الهم والحزن، ومن العجز والكسل، ومن الجبن والبخل"], "translations": {"en": {"title": "Reassurance in Fear, Panic, and Anxiety", "duas": ["Our Lord, pour upon us patience and plant firmly our feet and give us victory over the disbelieving people.", "Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.", "Sufficient for us is Allah, and He is the best Disposer of affairs.", "O Allah, I seek refuge in You from anxiety and sorrow, from incapacity and laziness, from cowardice and miserliness."]}, "fr": {"title": "Apaisement face à la peur, la panique et l''anxiété", "duas": ["Notre Seigneur, déverse sur nous la patience, affermis nos pas et accorde-nous la victoire sur les mécréants.", "Notre Seigneur, ne fais pas dévier nos cœurs après nous avoir guidés, et accorde-nous, venant de Toi, une miséricorde. C''est Toi, certes, le Grand Donateur.", "Allah nous suffit ; Il est le meilleur garant.", "Ô Allah, je cherche refuge auprès de Toi contre l''anxiété et la tristesse, contre l''incapacité et la paresse, contre la lâcheté et l''avarice."]}, "ur": {"title": "خوف، گھبراہٹ اور بے چینی کے وقت اطمینان", "duas": ["اے ہمارے رب! ہم پر صبر انڈیل دے، ہمارے قدم جما دے، اور کافر قوم کے مقابلے میں ہماری مدد فرما۔", "اے ہمارے رب! ہمیں ہدایت دینے کے بعد ہمارے دلوں کو ٹیڑھا نہ ہونے دے، اور اپنی طرف سے ہم پر رحمت نازل فرما، بیشک تو ہی سب سے بڑھ کر عطا فرمانے والا ہے۔", "ہمارے لیے اللہ کافی ہے اور وہ بہترین کارساز ہے۔", "اے اللہ! میں تیری پناہ مانگتا ہوں غم اور رنج سے، عاجزی اور سستی سے، اور بزدلی اور بخل سے۔"]}, "id": {"title": "Ketenangan Saat Takut, Cemas, dan Gelisah", "duas": ["Ya Tuhan kami, limpahkanlah kesabaran kepada kami, teguhkanlah pendirian kami, dan tolonglah kami menghadapi orang-orang kafir.", "Ya Tuhan kami, janganlah Engkau condongkan hati kami kepada kesesatan setelah Engkau beri petunjuk kepada kami, dan karuniakanlah kepada kami rahmat dari sisi-Mu. Sesungguhnya Engkaulah Maha Pemberi.", "Cukuplah Allah bagi kami, dan Dialah sebaik-baik pelindung.", "Ya Allah, aku berlindung kepada-Mu dari rasa cemas dan sedih, dari lemah dan malas, serta dari sifat pengecut dan kikir."]}, "ms": {"title": "Ketenangan Ketika Takut, Cemas, dan Gelisah", "duas": ["Wahai Tuhan kami, curahkanlah kesabaran ke atas kami, teguhkanlah pendirian kami, dan bantulah kami menentang kaum yang kafir.", "Wahai Tuhan kami, janganlah Engkau condongkan hati kami kepada kesesatan setelah Engkau beri petunjuk kepada kami, dan kurniakanlah kepada kami rahmat dari sisi-Mu. Sesungguhnya Engkaulah Maha Pemberi.", "Cukuplah Allah bagi kami, dan Dialah sebaik-baik pelindung.", "Ya Allah, aku berlindung kepada-Mu daripada rasa gelisah dan duka, daripada lemah dan malas, daripada sifat pengecut dan bakhil."]}, "hi": {"title": "डर, घबराहट और बेचैनी में सुकून", "duas": ["ऐ हमारे रब! हम पर सब्र उंडेल दे, हमारे क़दम जमा दे, और हमें काफ़िर क़ौम पर फ़तह अता कर।", "ऐ हमारे रब! जब तूने हमें हिदायत दे दी तो उसके बाद हमारे दिलों को टेढ़ा न कर, और अपने पास से हम पर रहमत नाज़िल फ़रमा। बेशक तू ही सबसे बड़ा अता करने वाला है।", "हमारे लिए अल्लाह काफ़ी है और वह बेहतरीन कारसाज़ है।", "हे अल्लाह! मैं तेरी पनाह माँगता हूँ ग़म और उदासी से, कमज़ोरी और सुस्ती से, बुज़दिली और कंजूसी से।"]}, "tr": {"title": "Korku, Panik ve Kaygı Anında Huzur", "duas": ["Rabbimiz! Üzerimize sabır yağdır, ayaklarımızı sabit kıl ve kâfirler topluluğuna karşı bize yardım et.", "Rabbimiz! Bizi hidayete erdirdikten sonra kalplerimizi eğriltme ve bize katından bir rahmet bağışla. Şüphesiz sen çok bağışlayansın.", "Allah bize yeter, O ne güzel vekildir.", "Allah''ım! Kederden ve hüzünden, acizlikten ve tembellikten, korkaklıktan ve cimrilikten sana sığınırım."]}, "bn": {"title": "ভয়, আতঙ্ক ও উদ্বেগের সময় প্রশান্তির দোয়া", "duas": ["হে আমাদের প্রতিপালক! আমাদের উপর ধৈর্য ঢেলে দিন, আমাদের পা দৃঢ় রাখুন এবং কাফির সম্প্রদায়ের বিরুদ্ধে আমাদেরকে সাহায্য করুন।", "হে আমাদের প্রতিপালক! আপনি আমাদেরকে হিদায়াত দেওয়ার পর আমাদের অন্তরকে বক্র করে দেবেন না, এবং আপনার পক্ষ থেকে আমাদেরকে রহমত দান করুন। নিশ্চয় আপনি মহাদাতা।", "আল্লাহই আমাদের জন্য যথেষ্ট, তিনি কতই না উত্তম কর্মবিধায়ক।", "হে আল্লাহ, আমি আপনার কাছে আশ্রয় প্রার্থনা করছি দুশ্চিন্তা ও দুঃখ থেকে, অক্ষমতা ও অলসতা থেকে, এবং কাপুরুষতা ও কৃপণতা থেকে।"]}, "ha": {"title": "Kwanciyar Hankali A Lokacin Tsoro Da Firgita Da Damuwa", "duas": ["Ya Ubangijinmu, ka zubo mana hakuri, ka tabbatar da kafafunmu, kuma ka taimake mu a kan mutanen kafirai.", "Ya Ubangijinmu, kada Ka karkatar da zukatanmu bayan da Ka shiryar da mu, kuma ka ba mu rahama daga wurinka. Lallai Kai ne Mabayarwa.", "Allah Ya isar mana, kuma Shi ne Mafi kyawon wakili.", "Ya Allah, ina neman tsari a gare ka daga damuwa da bakin ciki, daga rashin karfi da kasala, daga tsoro da rowa."]}}}, {"id": "relief", "title": "الفرج من الهم والحزن والضيق", "icon": "🌤️", "duas": ["لا إله إلا الله العظيم الحليم، لا إله إلا الله رب العرش العظيم، لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم", "لا إله إلا أنت سبحانك إني كنت من الظالمين", "اللهم لا سهل إلا ما جعلته سهلا، وأنت تجعل الحزن إذا شئت سهلا"], "translations": {"en": {"title": "Relief from Distress, Sorrow, and Hardship", "duas": ["There is no god but Allah, the Mighty, the Forbearing. There is no god but Allah, Lord of the Magnificent Throne. There is no god but Allah, Lord of the heavens and Lord of the earth and Lord of the Noble Throne.", "There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers.", "O Allah, there is no ease except in what You have made easy, and You make the difficult, if You will, easy."]}, "fr": {"title": "Le soulagement de l''angoisse, de la tristesse et de la détresse", "duas": ["Il n''y a de divinité qu''Allah, l''Immense, l''Indulgent. Il n''y a de divinité qu''Allah, le Seigneur du Trône immense. Il n''y a de divinité qu''Allah, le Seigneur des cieux, le Seigneur de la terre et le Seigneur du noble Trône.", "Il n''y a de divinité que Toi, gloire à Toi ! J''ai été, certes, du nombre des injustes.", "Ô Allah, rien n''est facile hormis ce que Tu rends facile, et Tu rends facile, si Tu le veux, ce qui est difficile."]}, "ur": {"title": "غم، رنج اور تنگی سے فرج", "duas": ["اللہ کے سوا کوئی معبود نہیں، وہ عظمت والا اور بردبار ہے۔ اللہ کے سوا کوئی معبود نہیں، وہ عرشِ عظیم کا رب ہے۔ اللہ کے سوا کوئی معبود نہیں، وہ آسمانوں کا رب ہے، زمین کا رب ہے اور عرشِ کریم کا رب ہے۔", "تیرے سوا کوئی معبود نہیں، تو پاک ہے، بیشک میں ظالموں میں سے تھا۔", "اے اللہ! کوئی چیز آسان نہیں سوائے اس کے جسے تو آسان بنا دے، اور تو چاہے تو مشکل کو بھی آسان بنا دیتا ہے۔"]}, "id": {"title": "Jalan Keluar dari Kesusahan, Kesedihan, dan Kesempitan", "duas": ["Tidak ada tuhan yang berhak disembah selain Allah Yang Maha Agung lagi Maha Penyantun. Tidak ada tuhan yang berhak disembah selain Allah, Tuhan Arsy yang agung. Tidak ada tuhan yang berhak disembah selain Allah, Tuhan langit dan Tuhan bumi serta Tuhan Arsy yang mulia.", "Tidak ada tuhan yang berhak disembah selain Engkau. Mahasuci Engkau, sesungguhnya aku termasuk orang-orang yang zalim.", "Ya Allah, tidak ada kemudahan kecuali apa yang Engkau jadikan mudah, dan Engkau menjadikan kesulitan, jika Engkau kehendaki, menjadi mudah."]}, "ms": {"title": "Kelegaan daripada Kesusahan, Kedukaan, dan Kesempitan", "duas": ["Tiada tuhan yang berhak disembah melainkan Allah Yang Maha Agung lagi Maha Penyantun. Tiada tuhan yang berhak disembah melainkan Allah, Tuhan Arasy yang agung. Tiada tuhan yang berhak disembah melainkan Allah, Tuhan langit dan Tuhan bumi serta Tuhan Arasy yang mulia.", "Tiada tuhan yang berhak disembah melainkan Engkau, Maha Suci Engkau, sesungguhnya aku adalah dari kalangan orang-orang yang zalim.", "Ya Allah, tiada kemudahan melainkan apa yang Engkau jadikan mudah, dan Engkaulah yang menjadikan kesukaran itu mudah apabila Engkau kehendaki."]}, "hi": {"title": "ग़म, उदासी और तंगी से राहत", "duas": ["अल्लाह के सिवा कोई माबूद नहीं, वह बड़ा अज़ीम, बड़ा बुर्दबार है। अल्लाह के सिवा कोई माबूद नहीं, वह अर्श-ए-अज़ीम का रब है। अल्लाह के सिवा कोई माबूद नहीं, वह आसमानों का रब, ज़मीन का रब और अर्श-ए-करीम का रब है।", "तेरे सिवा कोई माबूद नहीं, तू पाक है, बेशक मैं ज़ालिमों में से था।", "हे अल्लाह! कोई भी चीज़ आसान नहीं सिवाय उसके जिसे तूने आसान बना दिया, और तू चाहे तो ग़म को भी आसान बना देता है।"]}, "tr": {"title": "Keder, Hüzün ve Sıkıntıdan Kurtuluş", "duas": ["Allah''tan başka ilah yoktur; O, azametli ve halimdir. Allah''tan başka ilah yoktur; O, büyük Arş''ın Rabbidir. Allah''tan başka ilah yoktur; O, göklerin Rabbi, yerin Rabbi ve şerefli Arş''ın Rabbidir.", "Senden başka ilah yoktur. Seni tenzih ederim, gerçekten ben zalimlerden oldum.", "Allah''ım! Senin kolaylaştırdığından başka kolay yoktur; sen dilersen zoru da kolaylaştırırsın."]}, "bn": {"title": "দুশ্চিন্তা, দুঃখ ও সংকট থেকে মুক্তির দোয়া", "duas": ["আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি মহান, সহনশীল। আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি মহান আরশের প্রতিপালক। আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি আসমানসমূহের প্রতিপালক, জমিনের প্রতিপালক এবং সম্মানিত আরশের প্রতিপালক।", "আপনি ছাড়া কোনো ইলাহ নেই, আপনি পবিত্র মহান; নিশ্চয় আমি জালিমদের অন্তর্ভুক্ত ছিলাম।", "হে আল্লাহ, আপনি যা সহজ করেন তা ছাড়া কোনো কিছুই সহজ নয়, এবং আপনি চাইলে কঠিনকেও সহজ করে দেন।"]}, "ha": {"title": "Kubuta Daga Damuwa Da Bakin Ciki Da Kunci", "duas": ["Babu abin bautawa da gaskiya sai Allah, Mai girma, Mai hakuri. Babu abin bautawa da gaskiya sai Allah, Ubangijin Al''arshi mai girma. Babu abin bautawa da gaskiya sai Allah, Ubangijin sammai da Ubangijin kasa da Ubangijin Al''arshi mai daraja.", "Babu abin bautawa da gaskiya sai Kai, tsarki ya tabbata a gare Ka, lallai ni na kasance daga cikin azzalumai.", "Ya Allah, babu abin sauki sai abin da ka sauwake, kuma kana sanya wahala ta zama sauki idan Ka so."]}}}, {"id": "trust", "title": "التوكل وحسن الظن بالله والرضا", "icon": "🤲", "duas": ["ومن يتوكل على الله فهو حسبه إن الله بالغ أمره", "حسبي الله لا إله إلا هو عليه توكلت وهو رب العرش العظيم", "اللهم ارزقني الرضا بقضائك، والصبر على بلائك، وحسن الظن بك في كل حال"], "translations": {"en": {"title": "Trust in Allah, Good Thoughts of Him, and Contentment", "duas": ["And whoever relies upon Allah, then He is sufficient for him. Indeed, Allah will accomplish His purpose.", "Sufficient for me is Allah; there is no deity except Him. On Him I have relied, and He is the Lord of the Great Throne.", "O Allah, grant me contentment with Your decree, patience with Your trials, and good thoughts of You in every state."]}, "fr": {"title": "La confiance en Allah, la bonne opinion de Lui et la satisfaction", "duas": ["Et quiconque place sa confiance en Allah, Il lui suffit. Allah atteint certainement Son but.", "Allah me suffit ; il n''y a de divinité que Lui. En Lui je place ma confiance, et Il est le Seigneur du Trône immense.", "Ô Allah, accorde-moi la satisfaction envers Ton décret, la patience face à Tes épreuves, et une bonne opinion de Toi en toute circonstance."]}, "ur": {"title": "اللہ پر توکل، اس سے حسنِ ظن اور رضا", "duas": ["اور جو شخص اللہ پر بھروسہ کرے تو وہ اس کے لیے کافی ہے، بیشک اللہ اپنا کام پورا کر کے رہتا ہے۔", "مجھے اللہ کافی ہے، اس کے سوا کوئی معبود نہیں، میں نے اسی پر بھروسہ کیا اور وہ عرشِ عظیم کا رب ہے۔", "اے اللہ! مجھے اپنے فیصلے پر راضی رہنے، اپنی آزمائش پر صبر کرنے، اور ہر حال میں تجھ سے حسنِ ظن رکھنے کی توفیق دے۔"]}, "id": {"title": "Tawakal, Berbaik Sangka kepada Allah, dan Rida", "duas": ["Dan barang siapa bertawakal kepada Allah, niscaya Allah akan mencukupkan keperluannya. Sesungguhnya Allah melaksanakan urusan yang Dia kehendaki.", "Cukuplah Allah bagiku, tidak ada tuhan yang berhak disembah selain Dia. Hanya kepada-Nya aku bertawakal, dan Dialah Tuhan yang memiliki Arsy yang agung.", "Ya Allah, karuniakanlah kepadaku kerelaan menerima takdir-Mu, kesabaran atas ujian-Mu, dan husnuzan kepada-Mu dalam setiap keadaan."]}, "ms": {"title": "Tawakal, Sangka Baik kepada Allah, dan Redha", "duas": ["Dan sesiapa yang bertawakal kepada Allah, maka Dialah yang mencukupinya. Sesungguhnya Allah pasti menyempurnakan urusan-Nya.", "Cukuplah Allah bagiku, tiada tuhan yang berhak disembah melainkan Dia, kepada-Nya aku bertawakal, dan Dialah Tuhan Arasy yang agung.", "Ya Allah, kurniakanlah aku redha dengan ketentuan-Mu, sabar menghadapi ujian-Mu, dan sentiasa bersangka baik kepada-Mu dalam setiap keadaan."]}, "hi": {"title": "अल्लाह पर तवक्कुल, उससे अच्छा गुमान और रज़ा", "duas": ["और जो अल्लाह पर भरोसा करे तो वह उसके लिए काफ़ी है। बेशक अल्लाह अपना काम पूरा करने वाला है।", "मेरे लिए अल्लाह काफ़ी है, उसके सिवा कोई माबूद नहीं, मैंने उसी पर भरोसा किया और वह अर्श-ए-अज़ीम का रब है।", "हे अल्लाह! मुझे अपनी तक़दीर पर रज़ा, अपनी आज़माइश पर सब्र, और हर हाल में तेरे बारे में अच्छा गुमान अता कर।"]}, "tr": {"title": "Allah''a Tevekkül, O''na Güzel Zan Beslemek ve Rıza", "duas": ["Kim Allah''a tevekkül ederse O ona yeter. Şüphesiz Allah, emrini yerine getirendir.", "Allah bana yeter; O''ndan başka ilah yoktur. Ben yalnız O''na tevekkül ettim ve O, büyük Arş''ın Rabbidir.", "Allah''ım! Bana kaderine rıza göstermeyi, belana sabretmeyi ve her halde sana güzel zan beslemeyi nasip et."]}, "bn": {"title": "আল্লাহর প্রতি ভরসা, সুধারণা ও সন্তুষ্টি", "duas": ["যে আল্লাহর উপর ভরসা করে, তিনিই তার জন্য যথেষ্ট। নিশ্চয় আল্লাহ তাঁর কাজ সম্পন্নকারী।", "আল্লাহই আমার জন্য যথেষ্ট, তিনি ছাড়া কোনো ইলাহ নেই; আমি তাঁরই উপর ভরসা করেছি, আর তিনি মহান আরশের প্রতিপালক।", "হে আল্লাহ, আপনার ফয়সালার প্রতি সন্তুষ্টি, আপনার পরীক্ষায় ধৈর্য এবং সকল অবস্থায় আপনার প্রতি সুধারণা দান করুন।"]}, "ha": {"title": "Dogaro Ga Allah Da Kyakkyawan Zato A Gare Shi Da Yarda", "duas": ["Kuma wanda ya dogara ga Allah, to Shi ya isar masa. Lallai Allah Mai cika al''amarinsa ne.", "Allah Ya isar mini, babu abin bautawa da gaskiya sai Shi, a gare Shi na dogara, kuma Shi ne Ubangijin Al''arshi mai girma.", "Ya Allah, ka azurta ni da yarda da kadarar ka, da hakuri a kan jarabawar ka, da kuma kyakkyawan zato a gare ka a kowane hali."]}}}, {"id": "protection", "title": "الحفظ من الفتن والحسد والعين", "icon": "🛡️", "duas": ["اللهم إني أعوذ بك من الفتن ما ظهر منها وما بطن", "ربنا لا تجعلنا فتنة للذين كفروا واغفر لنا ربنا إنك أنت العزيز الحكيم", "أعوذ بكلمات الله التامات من شر ما خلق", "أعوذ بك من فتنة المحيا والممات"], "translations": {"en": {"title": "Protection from Trials, Envy, and the Evil Eye", "duas": ["O Allah, I seek refuge in You from trials, what is apparent of them and what is hidden.", "Our Lord, make us not a cause of persecution for the disbelievers, and forgive us, our Lord. Indeed, it is You who is the Exalted in Might, the Wise.", "I seek refuge in the perfect words of Allah from the evil of what He has created.", "I seek refuge in You from the trial of life and death."]}, "fr": {"title": "La protection contre les épreuves, l''envie et le mauvais œil", "duas": ["Ô Allah, je cherche refuge auprès de Toi contre les épreuves, apparentes ou cachées.", "Notre Seigneur, ne fais pas de nous une cible pour les mécréants, et pardonne-nous, notre Seigneur. C''est Toi, certes, le Puissant, le Sage.", "Je cherche refuge dans les paroles parfaites d''Allah contre le mal de ce qu''Il a créé.", "Je cherche refuge auprès de Toi contre l''épreuve de la vie et de la mort."]}, "ur": {"title": "فتنوں، حسد اور نظرِ بد سے حفاظت", "duas": ["اے اللہ! میں تیری پناہ مانگتا ہوں فتنوں سے، ان میں سے جو ظاہر ہیں اور جو پوشیدہ ہیں۔", "اے ہمارے رب! ہمیں کافروں کے لیے آزمائش کا نشانہ نہ بنا، اور ہمیں بخش دے، اے ہمارے رب! بیشک تو ہی زبردست، حکمت والا ہے۔", "میں اللہ کے کامل کلمات کی پناہ مانگتا ہوں ہر اس چیز کے شر سے جو اس نے پیدا کی۔", "میں تیری پناہ مانگتا ہوں زندگی اور موت کے فتنے سے۔"]}, "id": {"title": "Perlindungan dari Fitnah, Hasad, dan Pandangan Mata Jahat", "duas": ["Ya Allah, aku berlindung kepada-Mu dari fitnah, baik yang tampak maupun yang tersembunyi.", "Ya Tuhan kami, janganlah Engkau jadikan kami sasaran fitnah bagi orang-orang kafir, dan ampunilah kami, ya Tuhan kami. Sesungguhnya Engkaulah Yang Mahaperkasa lagi Mahabijaksana.", "Aku berlindung dengan kalimat-kalimat Allah yang sempurna dari kejahatan makhluk yang Dia ciptakan.", "Aku berlindung kepada-Mu dari fitnah kehidupan dan kematian."]}, "ms": {"title": "Perlindungan daripada Fitnah, Hasad, dan Pandangan Mata Jahat", "duas": ["Ya Allah, aku berlindung kepada-Mu daripada fitnah, yang zahir mahupun yang tersembunyi daripadanya.", "Wahai Tuhan kami, janganlah Engkau jadikan kami sebagai fitnah bagi orang-orang kafir, dan ampunkanlah kami, wahai Tuhan kami. Sesungguhnya Engkaulah Yang Maha Perkasa lagi Maha Bijaksana.", "Aku berlindung dengan kalimat-kalimat Allah yang sempurna daripada kejahatan makhluk yang diciptakan-Nya.", "Aku berlindung kepada-Mu daripada fitnah kehidupan dan kematian."]}, "hi": {"title": "फ़ितनों, हसद और नज़र से हिफ़ाज़त", "duas": ["हे अल्लाह! मैं तेरी पनाह माँगता हूँ फ़ितनों से, जो ज़ाहिर हैं उनसे भी और जो पोशीदा हैं उनसे भी।", "ऐ हमारे रब! हमें काफ़िरों के लिए फ़ितना न बना, और हमें बख़्श दे, ऐ हमारे रब! बेशक तू ही ग़ालिब, हिकमत वाला है।", "मैं अल्लाह के मुकम्मल कलिमात की पनाह में आता हूँ, हर उस चीज़ के शर से जो उसने पैदा की है।", "मैं तेरी पनाह माँगता हूँ ज़िंदगी और मौत के फ़ितने से।"]}, "tr": {"title": "Fitnelerden, Hasetten ve Nazardan Korunma", "duas": ["Allah''ım! Fitnelerin açığından da gizlisinden de sana sığınırım.", "Rabbimiz! Bizi inkâr edenler için bir fitne kılma, bizi bağışla Rabbimiz! Şüphesiz sen mutlak güç sahibi, hüküm ve hikmet sahibisin.", "Allah''ın eksiksiz kelimelerine, yarattığı şeylerin şerrinden sığınırım.", "Hayatın ve ölümün fitnesinden sana sığınırım."]}, "bn": {"title": "ফিতনা, হিংসা ও কুদৃষ্টি থেকে হেফাজতের দোয়া", "duas": ["হে আল্লাহ, আমি আপনার কাছে আশ্রয় প্রার্থনা করছি ফিতনা থেকে, তা প্রকাশ্য হোক বা গোপন।", "হে আমাদের প্রতিপালক! আমাদেরকে কাফিরদের জন্য পরীক্ষার বস্তু বানাবেন না, এবং আমাদেরকে ক্ষমা করুন, হে আমাদের প্রতিপালক! নিশ্চয় আপনি পরাক্রমশালী, প্রজ্ঞাময়।", "আমি আল্লাহর পরিপূর্ণ কালিমাসমূহের আশ্রয় গ্রহণ করছি তাঁর সৃষ্টির অনিষ্ট থেকে।", "আমি আপনার কাছে আশ্রয় প্রার্থনা করছি জীবন ও মৃত্যুর ফিতনা থেকে।"]}, "ha": {"title": "Tsari Daga Fitina Da Hassada Da Ido", "duas": ["Ya Allah, ina neman tsari a gare ka daga fitinu, wadanda suka bayyana da wadanda suka boyu.", "Ya Ubangijinmu, kada Ka sanya mu fitina ga wadanda suka kafirta, kuma ka gafarta mana, Ya Ubangijinmu. Lallai Kai ne Mabuwayi, Mai hikima.", "Ina neman tsari da cikakkun kalmomin Allah daga sharrin abin da Ya halitta.", "Ina neman tsari a gare ka daga fitinar rayuwa da mutuwa."]}}}, {"id": "provision", "title": "الرزق والمال والبركة", "icon": "💰", "duas": ["رب إني لما أنزلت إلي من خير فقير", "اللهم اكفني بحلالك عن حرامك، وأغنني بفضلك عمن سواك", "اللهم بارك لي فيما رزقتني، واخلف عليّ كل ما أنفقت في سبيلك", "اللهم إني أعوذ بك من الفقر، وأعوذ بك من قلة، ومن ذلة"], "translations": {"en": {"title": "Provision, Wealth, and Blessing", "duas": ["My Lord, indeed I am, for whatever good You would send down to me, in need.", "O Allah, suffice me with what You have made lawful instead of what You have made unlawful, and make me independent of all others besides You by Your grace.", "O Allah, bless me in what You have provided me, and replace for me all that I spend in Your cause.", "O Allah, I seek refuge in You from poverty, and I seek refuge in You from scarcity, and from abasement."]}, "fr": {"title": "La subsistance, les biens et la bénédiction", "duas": ["Seigneur, j''ai grand besoin du bien que Tu ferais descendre vers moi.", "Ô Allah, suffis-moi par ce que Tu as rendu licite plutôt que par ce que Tu as rendu illicite, et rends-moi, par Ta grâce, indépendant de tout autre que Toi.", "Ô Allah, bénis-moi dans ce que Tu m''as accordé, et remplace tout ce que je dépense dans Ta voie.", "Ô Allah, je cherche refuge auprès de Toi contre la pauvreté, et je cherche refuge auprès de Toi contre le manque et l''humiliation."]}, "ur": {"title": "رزق، مال اور برکت", "duas": ["اے میرے رب! جو بھلائی بھی تو مجھ پر نازل فرمائے میں اس کا محتاج ہوں۔", "اے اللہ! مجھے اپنے حلال کے ذریعے حرام سے بچا لے، اور اپنے فضل سے مجھے اپنے سوا سب سے بے نیاز کر دے۔", "اے اللہ! جو کچھ تو نے مجھے عطا کیا ہے اس میں برکت عطا فرما، اور جو کچھ میں تیری راہ میں خرچ کروں اس کا نعم البدل عطا فرما۔", "اے اللہ! میں تیری پناہ مانگتا ہوں فقر سے، اور کمی سے، اور ذلت سے۔"]}, "id": {"title": "Rezeki, Harta, dan Keberkahan", "duas": ["Ya Tuhanku, sesungguhnya aku sangat memerlukan sesuatu kebaikan yang Engkau turunkan kepadaku.", "Ya Allah, cukupkanlah aku dengan yang halal dari-Mu sehingga aku tidak membutuhkan yang haram, dan kayakanlah aku dengan karunia-Mu sehingga aku tidak membutuhkan selain-Mu.", "Ya Allah, berkahilah aku pada rezeki yang telah Engkau berikan, dan gantilah setiap apa yang aku infakkan di jalan-Mu.", "Ya Allah, aku berlindung kepada-Mu dari kefakiran, dan aku berlindung kepada-Mu dari kekurangan dan kehinaan."]}, "ms": {"title": "Rezeki, Harta, dan Keberkatan", "duas": ["Wahai Tuhanku, sesungguhnya aku amat memerlukan sebarang kebaikan yang Engkau turunkan kepadaku.", "Ya Allah, cukupkanlah aku dengan yang halal daripada-Mu sehingga aku tidak memerlukan yang haram, dan kayakanlah aku dengan limpah kurnia-Mu sehingga aku tidak memerlukan selain-Mu.", "Ya Allah, berkatilah aku pada rezeki yang telah Engkau kurniakan, dan gantikanlah bagiku segala yang aku belanjakan pada jalan-Mu.", "Ya Allah, aku berlindung kepada-Mu daripada kefakiran, dan aku berlindung kepada-Mu daripada kekurangan dan kehinaan."]}, "hi": {"title": "रोज़ी, माल और बरकत", "duas": ["मेरे रब! तू जो भी भलाई मुझ पर नाज़िल करे, मैं उसका मोहताज हूँ।", "हे अल्लाह! अपने हलाल से मुझे इतना दे कि मैं हराम से बेनियाज़ हो जाऊँ, और अपने फ़ज़ल से मुझे इतना दे कि तेरे सिवा किसी और का मोहताज न रहूँ।", "हे अल्लाह! जो कुछ तूने मुझे दिया है उसमें बरकत दे, और जो कुछ मैं तेरी राह में ख़र्च करूँ उसका बदला मुझे अता कर।", "हे अल्लाह! मैं तेरी पनाह माँगता हूँ मोहताजी से, और तेरी पनाह माँगता हूँ कमी से और ज़िल्लत से।"]}, "tr": {"title": "Rızık, Mal ve Bereket", "duas": ["Rabbim! Doğrusu bana indireceğin her hayra muhtacım.", "Allah''ım! Haramından koru, helalinle bana yeter kıl; lütfunla beni senden başkasına muhtaç etme.", "Allah''ım! Bana verdiğin rızıkta bereket ver, senin yolunda harcadığım her şeyin yerine daha hayırlısını koy.", "Allah''ım! Fakirlikten sana sığınırım, kıtlıktan ve zilletten de sana sığınırım."]}, "bn": {"title": "রিযিক, সম্পদ ও বরকতের দোয়া", "duas": ["হে আমার প্রতিপালক! আপনি আমার প্রতি যে কল্যাণই নাযিল করুন না কেন, আমি তার মুখাপেক্ষী।", "হে আল্লাহ, আপনার হালাল দিয়ে আমাকে আপনার হারাম থেকে অমুখাপেক্ষী করুন, এবং আপনার অনুগ্রহে আপনি ছাড়া অন্য সবার থেকে আমাকে অভাবমুক্ত করুন।", "হে আল্লাহ, আপনি আমাকে যা দান করেছেন তাতে বরকত দিন, এবং আপনার পথে আমি যা কিছু ব্যয় করি তার প্রতিদান দিন।", "হে আল্লাহ, আমি আপনার কাছে আশ্রয় প্রার্থনা করছি দারিদ্র্য থেকে, এবং আশ্রয় প্রার্থনা করছি অভাব থেকে ও লাঞ্ছনা থেকে।"]}, "ha": {"title": "Arziki Da Dukiya Da Albarka", "duas": ["Ya Ubangijina, lallai ni mai bukata ne ga duk wani alheri da za ka saukar mini.", "Ya Allah, ka wadatar da ni da halal daga haram, kuma ka wadatar da ni da falalarka daga bukatar wani baicin Kai.", "Ya Allah, ka sanya albarka a cikin abin da ka azurta ni, kuma ka maido mini duk abin da na kashe a hanyarka.", "Ya Allah, ina neman tsari a gare ka daga talauci, kuma ina neman tsari a gare ka daga karanci, da kuma kaskanci."]}}}, {"id": "work", "title": "العمل والتجارة والتوفيق", "icon": "💼", "duas": ["اللهم إني أسألك علما نافعا ورزقا طيبا وعملا متقبلا", "اللهم افتح لي أبواب الخير والرزق من حيث أحتسب ومن حيث لا أحتسب", "رب يسّر ولا تعسّر، وتمم بالخير"], "translations": {"en": {"title": "Work, Trade, and Success", "duas": ["O Allah, I ask You for beneficial knowledge, good provision, and acceptable deeds.", "O Allah, open for me the doors of good and provision from where I expect and from where I do not expect.", "My Lord, make it easy and do not make it difficult, and bring it to completion with good."]}, "fr": {"title": "Le travail, le commerce et la réussite", "duas": ["Ô Allah, je Te demande une science utile, une subsistance bonne et une œuvre agréée.", "Ô Allah, ouvre-moi les portes du bien et de la subsistance, d''où je m''y attends et d''où je ne m''y attends pas.", "Seigneur, facilite et ne complique pas, et achève cela dans le bien."]}, "ur": {"title": "کام، تجارت اور کامیابی", "duas": ["اے اللہ! میں تجھ سے نفع بخش علم، پاکیزہ رزق اور قبول شدہ عمل مانگتا ہوں۔", "اے اللہ! میرے لیے بھلائی اور رزق کے دروازے کھول دے، جہاں سے میں سوچوں اور جہاں سے میں نہ سوچوں۔", "اے میرے رب! آسانی فرما، مشکل نہ بنا، اور اسے بھلائی کے ساتھ مکمل فرما۔"]}, "id": {"title": "Pekerjaan, Perniagaan, dan Kesuksesan", "duas": ["Ya Allah, aku memohon kepada-Mu ilmu yang bermanfaat, rezeki yang baik, dan amal yang diterima.", "Ya Allah, bukakanlah bagiku pintu-pintu kebaikan dan rezeki, dari arah yang aku duga maupun yang tidak aku duga.", "Ya Tuhanku, mudahkanlah dan jangan Engkau persulit, dan sempurnakanlah dengan kebaikan."]}, "ms": {"title": "Pekerjaan, Perniagaan, dan Kejayaan", "duas": ["Ya Allah, aku memohon kepada-Mu ilmu yang bermanfaat, rezeki yang baik, dan amalan yang diterima.", "Ya Allah, bukakanlah untukku pintu-pintu kebaikan dan rezeki daripada arah yang aku sangka mahupun yang tidak aku sangka.", "Wahai Tuhanku, mudahkanlah urusan ini dan janganlah Engkau sukarkan, serta sempurnakanlah dengan kebaikan."]}, "hi": {"title": "काम, तिजारत और कामयाबी", "duas": ["हे अल्लाह! मैं तुझसे नफ़ा बख़्श इल्म, पाकीज़ा रोज़ी और मक़बूल अमल माँगता हूँ।", "हे अल्लाह! मेरे लिए भलाई और रोज़ी के दरवाज़े खोल दे, जहाँ से मुझे उम्मीद हो और जहाँ से मुझे उम्मीद न हो।", "मेरे रब! आसान कर, मुश्किल न कर, और भलाई के साथ पूरा फ़रमा।"]}, "tr": {"title": "İş, Ticaret ve Başarı", "duas": ["Allah''ım! Senden faydalı ilim, temiz rızık ve kabul edilen amel isterim.", "Allah''ım! Hayır ve rızık kapılarını, umduğum ve ummadığım yerlerden bana aç.", "Rabbim! Kolaylaştır, zorlaştırma; hayırla tamamla."]}, "bn": {"title": "কর্ম, ব্যবসা ও সাফল্যের দোয়া", "duas": ["হে আল্লাহ, আমি আপনার কাছে উপকারী জ্ঞান, পবিত্র রিযিক এবং কবুলযোগ্য আমল প্রার্থনা করছি।", "হে আল্লাহ, আমার জন্য কল্যাণ ও রিযিকের দরজাগুলো খুলে দিন, যেখান থেকে আমি আশা করি এবং যেখান থেকে আশা করি না সেখান থেকেও।", "হে আমার প্রতিপালক! সহজ করে দিন, কঠিন করবেন না, এবং কল্যাণের সাথে সম্পন্ন করুন।"]}, "ha": {"title": "Aiki Da Kasuwanci Da Nasara", "duas": ["Ya Allah, ina rokon ka ilimi mai amfani, da arziki mai kyau, da aiki wanda ake karba.", "Ya Allah, ka bude mini kofofin alheri da arziki daga inda nake tsammani da kuma daga inda ba na tsammani.", "Ya Ubangijina, ka sauwake kada Ka wahalar da ni, kuma ka kammala da alheri."]}}}, {"id": "knowledge", "title": "العلم والفهم والحفظ", "icon": "📚", "duas": ["رب زدني علما", "اللهم لا سهل إلا ما جعلته سهلا، وأنت تجعل الحزن إذا شئت سهلا", "اللهم علّمني ما ينفعني، وانفعني بما علمتني، وزدني علما"], "translations": {"en": {"title": "Knowledge, Understanding, and Retention", "duas": ["My Lord, increase me in knowledge.", "O Allah, there is no ease except in what You have made easy, and You make the difficult, if You will, easy.", "O Allah, teach me that which benefits me, benefit me by that which You have taught me, and increase me in knowledge."]}, "fr": {"title": "Le savoir, la compréhension et la mémorisation", "duas": ["Seigneur, augmente-moi en savoir.", "Ô Allah, rien n''est facile hormis ce que Tu rends facile, et Tu rends facile, si Tu le veux, ce qui est difficile.", "Ô Allah, enseigne-moi ce qui m''est utile, rends-moi utile ce que Tu m''as enseigné, et augmente-moi en savoir."]}, "ur": {"title": "علم، سمجھ اور یادداشت", "duas": ["اے میرے رب! میرے علم میں اضافہ فرما۔", "اے اللہ! کوئی چیز آسان نہیں سوائے اس کے جسے تو آسان بنا دے، اور تو چاہے تو مشکل کو بھی آسان بنا دیتا ہے۔", "اے اللہ! مجھے وہ سکھا جو میرے لیے نفع بخش ہو، اور مجھے اس علم سے فائدہ پہنچا جو تو نے مجھے سکھایا ہے، اور میرے علم میں اضافہ فرما۔"]}, "id": {"title": "Ilmu, Pemahaman, dan Hafalan", "duas": ["Ya Tuhanku, tambahkanlah ilmu kepadaku.", "Ya Allah, tidak ada kemudahan kecuali apa yang Engkau jadikan mudah, dan Engkau menjadikan kesulitan, jika Engkau kehendaki, menjadi mudah.", "Ya Allah, ajarkanlah kepadaku apa yang bermanfaat bagiku, berilah aku manfaat dengan apa yang telah Engkau ajarkan kepadaku, dan tambahkanlah ilmu kepadaku."]}, "ms": {"title": "Ilmu, Kefahaman, dan Kekuatan Hafazan", "duas": ["Wahai Tuhanku, tambahkanlah ilmu kepadaku.", "Ya Allah, tiada kemudahan melainkan apa yang Engkau jadikan mudah, dan Engkaulah yang menjadikan kesukaran itu mudah apabila Engkau kehendaki.", "Ya Allah, ajarkanlah kepadaku apa yang bermanfaat bagiku, berikanlah manfaat kepadaku daripada apa yang telah Engkau ajarkan, dan tambahkanlah ilmu kepadaku."]}, "hi": {"title": "इल्म, समझ और याददाश्त", "duas": ["मेरे रब! मेरे इल्म में इज़ाफ़ा फ़रमा।", "हे अल्लाह! कोई भी चीज़ आसान नहीं सिवाय उसके जिसे तूने आसान बना दिया, और तू चाहे तो ग़म को भी आसान बना देता है।", "हे अल्लाह! मुझे वह सिखा जो मेरे लिए नफ़ा बख़्श हो, और मुझे उससे नफ़ा पहुँचा जो तूने मुझे सिखाया है, और मेरे इल्म में इज़ाफ़ा फ़रमा।"]}, "tr": {"title": "İlim, Anlayış ve Ezber", "duas": ["Rabbim! İlmimi artır.", "Allah''ım! Senin kolaylaştırdığından başka kolay yoktur; sen dilersen zoru da kolaylaştırırsın.", "Allah''ım! Bana faydalı olanı öğret, bana öğrettiğinle beni faydalandır ve ilmimi artır."]}, "bn": {"title": "জ্ঞান, উপলব্ধি ও স্মরণশক্তির দোয়া", "duas": ["হে আমার প্রতিপালক! আমার জ্ঞান বৃদ্ধি করে দিন।", "হে আল্লাহ, আপনি যা সহজ করেন তা ছাড়া কোনো কিছুই সহজ নয়, এবং আপনি চাইলে কঠিনকেও সহজ করে দেন।", "হে আল্লাহ, আমাকে এমন জ্ঞান শিক্ষা দিন যা আমার উপকারে আসে, আপনি আমাকে যা শিখিয়েছেন তা দিয়ে আমাকে উপকৃত করুন, এবং আমার জ্ঞান বৃদ্ধি করে দিন।"]}, "ha": {"title": "Ilimi Da Fahimta Da Hazaka", "duas": ["Ya Ubangijina, ka kara mini ilimi.", "Ya Allah, babu abin sauki sai abin da ka sauwake, kuma kana sanya wahala ta zama sauki idan Ka so.", "Ya Allah, ka koya mini abin da zai amfane ni, kuma ka amfane ni da abin da ka koya mini, kuma ka kara mini ilimi."]}}}, {"id": "health", "title": "الصحة والشفاء", "icon": "💊", "duas": ["اللهم رب الناس أذهب البأس، اشف أنت الشافي، لا شفاء إلا شفاؤك، شفاءً لا يغادر سقما", "اللهم عافني في بدني، اللهم عافني في سمعي، اللهم عافني في بصري", "اللهم إني أسألك العافية في الدنيا والآخرة"], "translations": {"en": {"title": "Health and Healing", "duas": ["O Allah, Lord of mankind, remove the affliction and heal, for You are the Healer. There is no healing but Your healing, a healing that leaves no illness behind.", "O Allah, grant wellbeing to my body. O Allah, grant wellbeing to my hearing. O Allah, grant wellbeing to my sight.", "O Allah, I ask You for wellbeing in this world and the Hereafter."]}, "fr": {"title": "La santé et la guérison", "duas": ["Ô Allah, Seigneur des hommes, dissipe le mal et guéris, car c''est Toi le Guérisseur. Il n''y a de guérison que la Tienne, une guérison qui ne laisse aucune maladie.", "Ô Allah, accorde le bien-être à mon corps. Ô Allah, accorde le bien-être à mon ouïe. Ô Allah, accorde le bien-être à ma vue.", "Ô Allah, je Te demande le bien-être ici-bas et dans l''au-delà."]}, "ur": {"title": "صحت اور شفا", "duas": ["اے اللہ! لوگوں کے رب! تکلیف دور فرما اور شفا عطا فرما، تو ہی شفا دینے والا ہے، تیری شفا کے سوا کوئی شفا نہیں، ایسی شفا جو کوئی مرض باقی نہ چھوڑے۔", "اے اللہ! میرے بدن کو عافیت عطا فرما، اے اللہ! میرے کان کو عافیت عطا فرما، اے اللہ! میری آنکھ کو عافیت عطا فرما۔", "اے اللہ! میں تجھ سے دنیا اور آخرت میں عافیت مانگتا ہوں۔"]}, "id": {"title": "Kesehatan dan Kesembuhan", "duas": ["Ya Allah, Tuhan manusia, hilangkanlah penyakit ini, sembuhkanlah, Engkaulah Yang Maha Menyembuhkan, tidak ada kesembuhan kecuali kesembuhan dari-Mu, kesembuhan yang tidak meninggalkan penyakit.", "Ya Allah, berilah kesehatan pada badanku. Ya Allah, berilah kesehatan pada pendengaranku. Ya Allah, berilah kesehatan pada penglihatanku.", "Ya Allah, aku memohon kepada-Mu keselamatan di dunia dan akhirat."]}, "ms": {"title": "Kesihatan dan Penyembuhan", "duas": ["Ya Allah, Tuhan sekalian manusia, hilangkanlah kesakitan ini, sembuhkanlah, Engkaulah Yang Maha Menyembuhkan, tiada kesembuhan melainkan kesembuhan daripada-Mu, kesembuhan yang tidak meninggalkan sebarang penyakit.", "Ya Allah, sihatkanlah tubuh badanku. Ya Allah, sihatkanlah pendengaranku. Ya Allah, sihatkanlah penglihatanku.", "Ya Allah, aku memohon kepada-Mu kesejahteraan di dunia dan di akhirat."]}, "hi": {"title": "सेहत और शिफ़ा", "duas": ["हे अल्लाह! लोगों के रब! तकलीफ़ को दूर कर दे, शिफ़ा दे, तू ही शिफ़ा देने वाला है, तेरी शिफ़ा के सिवा कोई शिफ़ा नहीं, ऐसी शिफ़ा जो कोई बीमारी बाक़ी न छोड़े।", "हे अल्लाह! मेरे बदन को आफ़ियत दे। हे अल्लाह! मेरे कानों को आफ़ियत दे। हे अल्लाह! मेरी आँखों को आफ़ियत दे।", "हे अल्लाह! मैं तुझसे दुनिया और आख़िरत में आफ़ियत माँगता हूँ।"]}, "tr": {"title": "Sağlık ve Şifa", "duas": ["Allah''ım! Ey insanların Rabbi! Sıkıntıyı gider, şifa ver, sen şifa verensin. Senin şifandan başka şifa yoktur; öyle bir şifa ver ki hiçbir hastalık bırakmasın.", "Allah''ım! Bedenime afiyet ver. Allah''ım! Kulağıma afiyet ver. Allah''ım! Gözüme afiyet ver.", "Allah''ım! Senden dünyada ve ahirette afiyet isterim."]}, "bn": {"title": "স্বাস্থ্য ও আরোগ্যের দোয়া", "duas": ["হে আল্লাহ, মানুষের প্রতিপালক! কষ্ট দূর করুন, আরোগ্য দান করুন, আপনিই আরোগ্যদাতা; আপনার আরোগ্য ছাড়া কোনো আরোগ্য নেই—এমন আরোগ্য যা কোনো রোগ অবশিষ্ট রাখে না।", "হে আল্লাহ, আমার শরীরে সুস্থতা দান করুন। হে আল্লাহ, আমার শ্রবণশক্তিতে সুস্থতা দান করুন। হে আল্লাহ, আমার দৃষ্টিশক্তিতে সুস্থতা দান করুন।", "হে আল্লাহ, আমি আপনার কাছে দুনিয়া ও আখিরাতে সুস্থতা-নিরাপত্তা প্রার্থনা করছি।"]}, "ha": {"title": "Lafiya Da Warkarwa", "duas": ["Ya Allah, Ubangijin mutane, ka kawar da cutar, ka warkar da ita, Kai ne Mai warkarwa, babu warkarwa sai warkarwarka, warkarwa da ba ta barin wata cuta.", "Ya Allah, ka ba ni lafiya a jikina. Ya Allah, ka ba ni lafiya a jin na. Ya Allah, ka ba ni lafiya a ganina.", "Ya Allah, ina rokon ka lafiya a duniya da lahira."]}}}, {"id": "forgiveness", "title": "المغفرة والتوبة والاستغفار", "icon": "🌙", "duas": ["ربنا ظلمنا أنفسنا وإن لم تغفر لنا وترحمنا لنكونن من الخاسرين", "رب اغفر وارحم وأنت خير الراحمين", "أستغفر الله العظيم الذي لا إله إلا هو الحي القيوم وأتوب إليه", "سيد الاستغفار كاملًا موجود في أذكار الصباح"], "translations": {"en": {"title": "Forgiveness, Repentance, and Seeking Pardon", "duas": ["Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers.", "My Lord, forgive and have mercy, and You are the best of those who show mercy.", "I seek the forgiveness of Allah, the Mighty, whom there is no god but He, the Ever-Living, the Sustainer, and I repent to Him.", "The full ''Master of Seeking Forgiveness'' can be found in the Morning Remembrances section."]}, "fr": {"title": "Le pardon, le repentir et la demande de pardon", "duas": ["Notre Seigneur, nous nous sommes fait du tort à nous-mêmes ; et si Tu ne nous pardonnes pas et ne nous fais pas miséricorde, nous serons certainement du nombre des perdants.", "Seigneur, pardonne et fais miséricorde, Tu es le meilleur des miséricordieux.", "Je demande pardon à Allah, l''Immense, en dehors de qui il n''y a de divinité, le Vivant, l''Immuable, et je me repens à Lui.", "Le « Maître de la demande de pardon » complet se trouve dans la section des Invocations du matin."]}, "ur": {"title": "مغفرت، توبہ اور استغفار", "duas": ["اے ہمارے رب! ہم نے اپنی جانوں پر ظلم کیا، اور اگر تو نے ہمیں نہ بخشا اور ہم پر رحم نہ کیا تو ہم یقیناً نقصان اٹھانے والوں میں سے ہو جائیں گے۔", "اے میرے رب! بخش دے اور رحم فرما، اور تو سب سے بہتر رحم فرمانے والا ہے۔", "میں اللہ عظیم سے مغفرت مانگتا ہوں جس کے سوا کوئی معبود نہیں، جو زندہ اور ہر چیز کا نگہبان ہے، اور میں اسی کی طرف توبہ کرتا ہوں۔", "سیدُ الاستغفار کی مکمل دعا صبح کے اذکار کے حصے میں موجود ہے۔"]}, "id": {"title": "Ampunan, Tobat, dan Istigfar", "duas": ["Ya Tuhan kami, kami telah menzalimi diri kami sendiri. Jika Engkau tidak mengampuni kami dan memberi rahmat kepada kami, niscaya kami termasuk orang-orang yang rugi.", "Ya Tuhanku, berilah ampunan dan rahmat, dan Engkau adalah pemberi rahmat yang terbaik.", "Aku memohon ampun kepada Allah Yang Maha Agung, yang tidak ada tuhan yang berhak disembah selain Dia, Yang Mahahidup lagi terus-menerus mengurus makhluk-Nya, dan aku bertobat kepada-Nya.", "Sayyidul Istigfar (doa istigfar yang paling utama) secara lengkap dapat ditemukan pada bagian Dzikir Pagi."]}, "ms": {"title": "Keampunan, Taubat, dan Istighfar", "duas": ["Wahai Tuhan kami, kami telah menzalimi diri kami sendiri, dan jika Engkau tidak mengampuni kami serta merahmati kami, nescaya kami termasuk dalam golongan orang-orang yang rugi.", "Wahai Tuhanku, ampunilah dan berilah rahmat, dan Engkaulah sebaik-baik pemberi rahmat.", "Aku memohon keampunan daripada Allah Yang Maha Agung, yang tiada tuhan yang berhak disembah melainkan Dia, Yang Maha Hidup lagi Maha Berdiri Sendiri (mentadbir sekalian makhluk-Nya), dan aku bertaubat kepada-Nya.", "Sayyidul Istighfar secara lengkap boleh didapati dalam bahagian Zikir Pagi."]}, "hi": {"title": "मग़फ़िरत, तौबा और इस्तिग़फ़ार", "duas": ["ऐ हमारे रब! हमने अपने ऊपर ज़ुल्म किया, और अगर तूने हमें न बख़्शा और हम पर रहम न किया तो यक़ीनन हम घाटा उठाने वालों में से हो जाएँगे।", "मेरे रब! बख़्श दे और रहम फ़रमा, तू सबसे बेहतर रहम करने वाला है।", "मैं अल्लाह अज़ीम से इस्तिग़फ़ार करता हूँ, जिसके सिवा कोई माबूद नहीं, जो ज़िंदा है, हमेशा क़ायम रहने वाला है, और मैं उसी की तरफ़ तौबा करता हूँ।", "मुकम्मल ''सैयिदुल इस्तिग़फ़ार'' सुबह के अज़कार सेक्शन में मौजूद है।"]}, "tr": {"title": "Mağfiret, Tövbe ve İstiğfar", "duas": ["Rabbimiz! Biz kendimize zulmettik; eğer bizi bağışlamaz ve bize merhamet etmezsen mutlaka kaybedenlerden oluruz.", "Rabbim! Bağışla ve merhamet et; sen merhamet edenlerin en hayırlısısın.", "Kendisinden başka ilah olmayan, diri ve her şeyi ayakta tutan yüce Allah''tan bağışlanma diler ve O''na tövbe ederim.", "İstiğfarın efendisi olan duanın tam metni Sabah Zikirleri bölümünde bulunmaktadır."]}, "bn": {"title": "ক্ষমা, তাওবা ও ইস্তিগফারের দোয়া", "duas": ["হে আমাদের প্রতিপালক! আমরা নিজেদের প্রতি জুলুম করেছি, আর যদি আপনি আমাদেরকে ক্ষমা না করেন এবং আমাদের প্রতি দয়া না করেন, তবে আমরা অবশ্যই ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হয়ে যাব।", "হে আমার প্রতিপালক! ক্ষমা করুন এবং দয়া করুন, আর আপনিই দয়াশীলদের মধ্যে শ্রেষ্ঠ।", "আমি মহান আল্লাহর কাছে ক্ষমা প্রার্থনা করছি, যিনি ব্যতীত কোনো ইলাহ নেই, যিনি চিরঞ্জীব, চিরপ্রতিষ্ঠিত, এবং আমি তাঁরই কাছে তাওবা করছি।", "সাইয়্যিদুল ইস্তিগফার সম্পূর্ণভাবে সকালের যিকিরসমূহ অংশে পাওয়া যাবে।"]}, "ha": {"title": "Gafara Da Tuba Da Neman Gafara", "duas": ["Ya Ubangijinmu, mun zalunci kanmu, kuma idan ba ka gafarta mana ba, ka yi mana rahama, hakika za mu kasance daga cikin masu hasara.", "Ya Ubangijina, ka gafarta, ka yi rahama, kuma Kai ne Mafi alherin masu rahama.", "Ina neman gafarar Allah Mai girma, wanda babu abin bautawa da gaskiya sai Shi, Rayayye, Mai tsayuwa da kome, kuma ina tuba zuwa gare Shi.", "Cikakken ''Shugaban Neman Gafara'' ana samunsa a sashin Azkarin Safiya."]}}}, {"id": "husn-khatima", "title": "حسن الخاتمة", "icon": "✨", "duas": ["اللهم اجعل خير عمري آخره، وخير عملي خواتمه، وخير أيامي يوم ألقاك", "اللهم إني أسألك الثبات عند الشهادتين عند الموت، ونطق الحق عند الرضا والغضب", "اللهم توفني مسلمًا وألحقني بالصالحين"], "translations": {"en": {"title": "A Good Ending", "duas": ["O Allah, make the best of my life its end, the best of my deeds their conclusion, and the best of my days the day I meet You.", "O Allah, I ask You for steadfastness upon the two testimonies of faith at the time of death, and for speaking the truth in both contentment and anger.", "O Allah, take my soul as a Muslim and join me with the righteous."]}, "fr": {"title": "La bonne fin", "duas": ["Ô Allah, fais que le meilleur de ma vie en soit la fin, que le meilleur de mes œuvres en soit la conclusion, et que le meilleur de mes jours soit celui où je Te rencontrerai.", "Ô Allah, je Te demande la fermeté dans les deux attestations de foi au moment de la mort, et de dire la vérité tant dans la satisfaction que dans la colère.", "Ô Allah, fais-moi mourir musulman et joins-moi aux vertueux."]}, "ur": {"title": "حسنِ خاتمہ", "duas": ["اے اللہ! میری زندگی کا بہترین حصہ اس کا آخری حصہ بنا، میرے اعمال کا بہترین حصہ اس کا اختتام بنا، اور میرے دنوں میں بہترین دن وہ بنا جس دن میں تجھ سے ملوں۔", "اے اللہ! میں تجھ سے موت کے وقت دونوں شہادتوں پر ثابت قدمی مانگتا ہوں، اور خوشی و غصے دونوں حالتوں میں حق بات کہنے کی توفیق مانگتا ہوں۔", "اے اللہ! مجھے مسلمان ہونے کی حالت میں وفات دے، اور مجھے نیک لوگوں کے ساتھ ملا دے۔"]}, "id": {"title": "Husnul Khatimah (Akhir yang Baik)", "duas": ["Ya Allah, jadikanlah sebaik-baik usiaku di penghujungnya, sebaik-baik amalku di akhirnya, dan sebaik-baik hariku adalah hari aku berjumpa dengan-Mu.", "Ya Allah, aku memohon kepada-Mu keteguhan mengucapkan dua kalimat syahadat saat kematian, dan ucapan yang benar baik dalam keadaan rida maupun marah.", "Ya Allah, wafatkanlah aku dalam keadaan muslim dan pertemukanlah aku dengan orang-orang yang saleh."]}, "ms": {"title": "Husnul Khatimah (Kesudahan yang Baik)", "duas": ["Ya Allah, jadikanlah sebaik-baik umurku pada penghujungnya, sebaik-baik amalanku pada penutupnya, dan sebaik-baik hariku pada hari aku menemui-Mu.", "Ya Allah, aku memohon kepada-Mu keteguhan mengucap dua kalimah syahadah ketika maut, serta bertutur benar sama ada dalam keadaan redha mahupun marah.", "Ya Allah, matikanlah aku dalam keadaan Islam dan gabungkanlah aku bersama orang-orang yang soleh."]}, "hi": {"title": "अच्छा अंजाम (हुस्न-ए-ख़ातिमा)", "duas": ["हे अल्लाह! मेरी ज़िंदगी का सबसे अच्छा हिस्सा उसका आख़िरी हिस्सा बना दे, मेरे अमल का सबसे अच्छा हिस्सा उसका अंत बना दे, और मेरे दिनों में सबसे अच्छा दिन वह बना दे जिस दिन मैं तुझसे मिलूँ।", "हे अल्लाह! मैं तुझसे मौत के वक़्त दोनों गवाहियों पर जमे रहने की, और रज़ामंदी और ग़ुस्से दोनों हालात में हक़ बात कहने की तौफ़ीक़ माँगता हूँ।", "हे अल्लाह! मुझे मुसलमान की हालत में मौत दे और मुझे नेक लोगों के साथ मिला दे।"]}, "tr": {"title": "Güzel Akıbet", "duas": ["Allah''ım! Ömrümün en hayırlısını sonunu, amellerimin en hayırlısını nihayetini, günlerimin en hayırlısını sana kavuşacağım günü kıl.", "Allah''ım! Ölüm anında iki şehadet kelimesi üzere sebat etmeyi, hoşnutlukta da öfkede de hakkı söylemeyi senden isterim.", "Allah''ım! Canımı Müslüman olarak al ve beni salihler arasına kat."]}, "bn": {"title": "উত্তম পরিণতির দোয়া", "duas": ["হে আল্লাহ, আমার জীবনের সর্বোত্তম অংশ তার শেষভাগে রাখুন, আমার আমলের সর্বোত্তম অংশ তার শেষ পরিণতিতে রাখুন, এবং আমার দিনগুলোর সর্বোত্তম দিন সেই দিন রাখুন যেদিন আমি আপনার সাথে সাক্ষাৎ করব।", "হে আল্লাহ, আমি আপনার কাছে মৃত্যুর সময় দুই সাক্ষ্যবাক্যের (কালিমা শাহাদাত) উপর অবিচলতা এবং সন্তুষ্টি ও রাগের অবস্থায় সত্য কথা বলার তাওফিক প্রার্থনা করছি।", "হে আল্লাহ, আমাকে মুসলিম অবস্থায় মৃত্যু দিন এবং আমাকে সৎকর্মশীলদের সাথে মিলিত করুন।"]}, "ha": {"title": "Kyakkyawan Karshe", "duas": ["Ya Allah, ka sanya mafi alherin rayuwata karshenta, mafi alherin aikina karshensa, kuma mafi alherin kwanakina ranar da zan hadu da Kai.", "Ya Allah, ina rokon ka tabbata a kan shaidun biyu (Shahada) a lokacin mutuwa, da kuma fadar gaskiya a lokacin yarda da fushi.", "Ya Allah, ka karbi raina ina musulmi, kuma ka hada ni da salihai."]}}}, {"id": "jannah-najah", "title": "العتق من النار ودخول الجنة", "icon": "🌿", "duas": ["اللهم أجرني من النار", "اللهم إني أسألك الجنة وما قرب إليها من قول أو عمل، وأعوذ بك من النار وما قرب إليها من قول أو عمل", "ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار"], "translations": {"en": {"title": "Freedom from the Fire and Entry into Paradise", "duas": ["O Allah, save me from the Fire.", "O Allah, I ask You for Paradise and whatever brings one closer to it in word or deed, and I seek refuge in You from the Fire and whatever brings one closer to it in word or deed.", "Our Lord, give us in this world that which is good and in the Hereafter that which is good and protect us from the punishment of the Fire."]}, "fr": {"title": "La délivrance du Feu et l''entrée au Paradis", "duas": ["Ô Allah, préserve-moi du Feu.", "Ô Allah, je Te demande le Paradis et tout ce qui en rapproche en parole ou en action, et je cherche refuge auprès de Toi contre le Feu et tout ce qui en rapproche en parole ou en action.", "Notre Seigneur, accorde-nous belle part ici-bas et belle part dans l''au-delà, et préserve-nous du châtiment du Feu."]}, "ur": {"title": "جہنم سے آزادی اور جنت میں داخلہ", "duas": ["اے اللہ! مجھے جہنم سے نجات عطا فرما۔", "اے اللہ! میں تجھ سے جنت اور اس کے قریب کرنے والے ہر قول و عمل کا سوال کرتا ہوں، اور جہنم اور اس کے قریب کرنے والے ہر قول و عمل سے تیری پناہ مانگتا ہوں۔", "اے ہمارے رب! ہمیں دنیا میں بھلائی عطا فرما اور آخرت میں بھی بھلائی عطا فرما، اور ہمیں جہنم کے عذاب سے بچا۔"]}, "id": {"title": "Terbebas dari Neraka dan Masuk Surga", "duas": ["Ya Allah, selamatkanlah aku dari neraka.", "Ya Allah, aku memohon kepada-Mu surga dan segala perkataan maupun perbuatan yang mendekatkan kepadanya, dan aku berlindung kepada-Mu dari neraka dan segala perkataan maupun perbuatan yang mendekatkan kepadanya.", "Ya Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan lindungilah kami dari azab neraka."]}, "ms": {"title": "Terlepas daripada Neraka dan Memasuki Syurga", "duas": ["Ya Allah, selamatkanlah aku daripada api neraka.", "Ya Allah, aku memohon kepada-Mu syurga serta apa jua yang mendekatkan kepadanya sama ada perkataan atau perbuatan, dan aku berlindung kepada-Mu daripada neraka serta apa jua yang mendekatkan kepadanya sama ada perkataan atau perbuatan.", "Wahai Tuhan kami, kurniakanlah kepada kami kebaikan di dunia dan kebaikan di akhirat, serta peliharalah kami daripada azab neraka."]}, "hi": {"title": "जहन्नम से आज़ादी और जन्नत में दाख़िला", "duas": ["हे अल्लाह! मुझे जहन्नम की आग से बचा।", "हे अल्लाह! मैं तुझसे जन्नत माँगता हूँ और वह हर बात और अमल जो उसके क़रीब करे, और मैं तेरी पनाह माँगता हूँ जहन्नम से और उस हर बात और अमल से जो उसके क़रीब करे।", "ऐ हमारे रब! हमें दुनिया में भलाई दे और आख़िरत में भी भलाई दे, और हमें आग के अज़ाब से बचा।"]}, "tr": {"title": "Cehennemden Azat Olmak ve Cennete Girmek", "duas": ["Allah''ım! Beni cehennem ateşinden koru.", "Allah''ım! Senden cenneti ve ona yaklaştıran söz ve amelleri isterim; cehennemden ve ona yaklaştıran söz ve amellerden de sana sığınırım.", "Rabbimiz! Bize dünyada iyilik, ahirette de iyilik ver ve bizi ateşin azabından koru."]}, "bn": {"title": "জাহান্নাম থেকে মুক্তি ও জান্নাতে প্রবেশের দোয়া", "duas": ["হে আল্লাহ, আমাকে জাহান্নাম থেকে রক্ষা করুন।", "হে আল্লাহ, আমি আপনার কাছে জান্নাত এবং যে কথা বা কাজ তার নিকটবর্তী করে তা প্রার্থনা করছি, আর আমি আপনার কাছে জাহান্নাম থেকে এবং যে কথা বা কাজ তার নিকটবর্তী করে তা থেকে আশ্রয় প্রার্থনা করছি।", "হে আমাদের প্রতিপালক! আমাদেরকে দুনিয়াতে কল্যাণ দিন এবং আখিরাতেও কল্যাণ দিন, এবং আমাদেরকে জাহান্নামের আযাব থেকে রক্ষা করুন।"]}, "ha": {"title": "''Yanci Daga Wuta Da Shiga Aljanna", "duas": ["Ya Allah, ka tsirar da ni daga Wuta.", "Ya Allah, ina rokon ka Aljanna da duk abin da zai kusantar da ni zuwa gare ta daga magana ko aiki, kuma ina neman tsari a gare ka daga Wuta da duk abin da zai kusantar da ni zuwa gare ta daga magana ko aiki.", "Ya Ubangijinmu, ka ba mu alheri a duniya da alheri a lahira, kuma ka tsare mu daga azabar Wuta."]}}}, {"id": "jawami", "title": "جوامع الدعاء (خير الدنيا والآخرة)", "icon": "🌸", "duas": ["ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار", "اللهم إني أسألك من الخير كله عاجله وآجله، ما علمت منه وما لم أعلم، وأعوذ بك من الشر كله عاجله وآجله، ما علمت منه وما لم أعلم", "اللهم اجعل لي من كل هم فرجا، ومن كل ضيق مخرجا، وارزقني من حيث لا أحتسب"], "translations": {"en": {"title": "Comprehensive Supplications (Good in This World and the Next)", "duas": ["Our Lord, give us in this world that which is good and in the Hereafter that which is good and protect us from the punishment of the Fire.", "O Allah, I ask You for all good, its near and its distant, what I know of it and what I do not know, and I seek refuge in You from all evil, its near and its distant, what I know of it and what I do not know.", "O Allah, grant me relief from every worry, a way out of every hardship, and provide for me from where I do not expect."]}, "fr": {"title": "Invocations englobantes (le bien de ce monde et de l''au-delà)", "duas": ["Notre Seigneur, accorde-nous belle part ici-bas et belle part dans l''au-delà, et préserve-nous du châtiment du Feu.", "Ô Allah, je Te demande tout le bien, son immédiat et son différé, ce que j''en connais et ce que j''en ignore, et je cherche refuge auprès de Toi contre tout le mal, son immédiat et son différé, ce que j''en connais et ce que j''en ignore.", "Ô Allah, accorde-moi une issue à chaque souci, une sortie à chaque détresse, et accorde-moi une subsistance d''où je ne m''y attends pas."]}, "ur": {"title": "جامع دعائیں (دنیا و آخرت کی بھلائی)", "duas": ["اے ہمارے رب! ہمیں دنیا میں بھلائی عطا فرما اور آخرت میں بھی بھلائی عطا فرما، اور ہمیں جہنم کے عذاب سے بچا۔", "اے اللہ! میں تجھ سے ہر بھلائی مانگتا ہوں، جلد ملنے والی بھی اور دیر سے ملنے والی بھی، جسے میں جانتا ہوں اور جسے نہیں جانتا، اور میں تیری پناہ مانگتا ہوں ہر برائی سے، جلد آنے والی بھی اور دیر سے آنے والی بھی، جسے میں جانتا ہوں اور جسے نہیں جانتا۔", "اے اللہ! میرے لیے ہر پریشانی سے نکلنے کی راہ بنا، ہر تنگی سے نکلنے کا راستہ بنا، اور مجھے ایسی جگہ سے رزق عطا فرما جہاں سے مجھے گمان بھی نہ ہو۔"]}, "id": {"title": "Doa-doa yang Menyeluruh (Kebaikan Dunia dan Akhirat)", "duas": ["Ya Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan lindungilah kami dari azab neraka.", "Ya Allah, aku memohon kepada-Mu segala kebaikan, yang segera maupun yang tertunda, yang aku ketahui maupun yang tidak aku ketahui, dan aku berlindung kepada-Mu dari segala keburukan, yang segera maupun yang tertunda, yang aku ketahui maupun yang tidak aku ketahui.", "Ya Allah, jadikanlah bagiku dari setiap kesusahan jalan keluar, dari setiap kesempitan jalan lapang, dan berilah aku rezeki dari arah yang tidak aku duga."]}, "ms": {"title": "Doa-Doa Ringkas yang Merangkumi Kebaikan Dunia dan Akhirat", "duas": ["Wahai Tuhan kami, kurniakanlah kepada kami kebaikan di dunia dan kebaikan di akhirat, serta peliharalah kami daripada azab neraka.", "Ya Allah, aku memohon kepada-Mu segala kebaikan, yang cepat mahupun yang lambat, yang aku ketahui mahupun yang tidak aku ketahui, dan aku berlindung kepada-Mu daripada segala kejahatan, yang cepat mahupun yang lambat, yang aku ketahui mahupun yang tidak aku ketahui.", "Ya Allah, kurniakanlah aku jalan keluar daripada setiap kegelisahan, jalan penyelesaian daripada setiap kesempitan, dan berikanlah aku rezeki daripada arah yang tidak aku sangka."]}, "hi": {"title": "जामे दुआएं (दुनिया और आख़िरत की भलाई)", "duas": ["ऐ हमारे रब! हमें दुनिया में भलाई दे और आख़िरत में भी भलाई दे, और हमें आग के अज़ाब से बचा।", "हे अल्लाह! मैं तुझसे हर भलाई माँगता हूँ, जल्दी वाली भी और देर वाली भी, जो मुझे मालूम है वह भी और जो मुझे मालूम नहीं वह भी, और मैं तेरी पनाह माँगता हूँ हर बुराई से, जल्दी वाली भी और देर वाली भी, जो मुझे मालूम है वह भी और जो मुझे मालूम नहीं वह भी।", "हे अल्लाह! मेरे लिए हर ग़म से राहत, हर तंगी से निकलने का रास्ता बना दे, और मुझे वहाँ से रोज़ी दे जहाँ से मुझे गुमान भी न हो।"]}, "tr": {"title": "Kapsamlı Dualar (Dünya ve Ahiret Hayrı)", "duas": ["Rabbimiz! Bize dünyada iyilik, ahirette de iyilik ver ve bizi ateşin azabından koru.", "Allah''ım! Bildiğim ve bilmediğim, çabuk geleni ve geç geleni ile bütün hayrı senden isterim; bildiğim ve bilmediğim, çabuk geleni ve geç geleni ile bütün şerden de sana sığınırım.", "Allah''ım! Bana her kederden bir çıkış, her sıkıntıdan bir kurtuluş yolu ver ve beni ummadığım yerden rızıklandır."]}, "bn": {"title": "সর্বাঙ্গীণ দোয়া (দুনিয়া ও আখিরাতের কল্যাণ)", "duas": ["হে আমাদের প্রতিপালক! আমাদেরকে দুনিয়াতে কল্যাণ দিন এবং আখিরাতেও কল্যাণ দিন, এবং আমাদেরকে জাহান্নামের আযাব থেকে রক্ষা করুন।", "হে আল্লাহ, আমি আপনার কাছে সমস্ত কল্যাণ প্রার্থনা করছি, তা তাৎক্ষণিক হোক বা বিলম্বিত, যা আমি জানি ও যা জানি না; আর আমি আপনার কাছে সমস্ত অনিষ্ট থেকে আশ্রয় প্রার্থনা করছি, তা তাৎক্ষণিক হোক বা বিলম্বিত, যা আমি জানি ও যা জানি না।", "হে আল্লাহ, প্রতিটি দুশ্চিন্তা থেকে আমার জন্য মুক্তির পথ রাখুন, প্রতিটি সংকট থেকে বের হওয়ার পথ রাখুন, এবং আমাকে এমন উৎস থেকে রিযিক দিন যা আমি ধারণাও করি না।"]}, "ha": {"title": "Cikakkun Addu''o''i (Alherin Duniya Da Lahira)", "duas": ["Ya Ubangijinmu, ka ba mu alheri a duniya da alheri a lahira, kuma ka tsare mu daga azabar Wuta.", "Ya Allah, ina rokon ka dukkan alheri, na yanzu da na gaba, wanda na sani da wanda ban sani ba, kuma ina neman tsari a gare ka daga dukkan sharri, na yanzu da na gaba, wanda na sani da wanda ban sani ba.", "Ya Allah, ka sanya mini kubuta daga kowace damuwa, da mafita daga kowane kunci, kuma ka azurta ni daga inda ba na tsammani."]}}}, {"id": "jumuah", "title": "أدعية يوم الجمعة", "icon": "🕌", "duas": ["أكثِر من الصلاة على النبي ﷺ يوم الجمعة وليلتها", "تحرّ ساعة الإجابة في آخر ساعة من عصر يوم الجمعة بالدعاء", "اللهم اجعل جمعتنا هذه مباركة، واغفر لنا فيها، وارحمنا"], "translations": {"en": {"title": "Friday Supplications", "duas": ["Send abundant blessings upon the Prophet ﷺ on Friday and its night.", "Seek the hour when supplications are answered, in the last hour of Friday afternoon, with dua.", "O Allah, make this Friday of ours blessed, forgive us in it, and have mercy on us."]}, "fr": {"title": "Invocations du vendredi", "duas": ["Multiplie les prières sur le Prophète ﷺ le vendredi et la nuit qui le précède.", "Recherche l''heure d''exaucement, dans la dernière heure de l''après-midi du vendredi, par l''invocation.", "Ô Allah, fais de ce vendredi un jour béni, pardonne-nous en ce jour, et fais-nous miséricorde."]}, "ur": {"title": "جمعہ کے دن کی دعائیں", "duas": ["جمعہ کے دن اور اس کی رات میں نبی کریم ﷺ پر کثرت سے درود بھیجیں۔", "جمعہ کے دن عصر کے بعد آخری گھڑی میں قبولیت کی گھڑی تلاش کر کے دعا کریں۔", "اے اللہ! ہمارے اس جمعہ کو بابرکت بنا، اس میں ہمیں بخش دے، اور ہم پر رحم فرما۔"]}, "id": {"title": "Doa-doa Hari Jumat", "duas": ["Perbanyaklah membaca selawat kepada Nabi ﷺ pada hari Jumat dan malamnya.", "Carilah waktu mustajab pada jam terakhir sore hari Jumat untuk berdoa.", "Ya Allah, jadikanlah Jumat kami ini penuh berkah, ampunilah kami di dalamnya, dan rahmatilah kami."]}, "ms": {"title": "Doa-Doa pada Hari Jumaat", "duas": ["Perbanyakkanlah selawat ke atas Nabi ﷺ pada hari Jumaat dan malamnya.", "Carilah saat mustajab doa pada waktu terakhir petang hari Jumaat dengan memperbanyakkan doa.", "Ya Allah, jadikanlah Jumaat kami ini penuh keberkatan, ampunilah kami padanya, dan rahmatilah kami."]}, "hi": {"title": "जुमे के दिन की दुआएं", "duas": ["जुमे के दिन और उसकी रात में नबी ﷺ पर ज़्यादा से ज़्यादा दरूद भेजें।", "जुमे के दिन अस्र के बाद के आख़िरी हिस्से में क़बूलियत की घड़ी तलाश करते हुए दुआ करें।", "हे अल्लाह! हमारे इस जुमे को बाबरकत बना, इसमें हमें बख़्श दे, और हम पर रहम फ़रमा।"]}, "tr": {"title": "Cuma Günü Duaları", "duas": ["Cuma günü ve gecesinde Peygamber''e (sallallahu aleyhi ve sellem) bol bol salavat getirin.", "Cuma günü ikindiden sonraki son saatte duanın kabul edildiği vakti dua ile ganimet bilin.", "Allah''ım! Bu cumamızı bereketli kıl, bizi bu günde bağışla ve bize merhamet et."]}, "bn": {"title": "জুমার দিনের দোয়া", "duas": ["জুমার দিন ও রাতে নবী ﷺ-এর প্রতি বেশি বেশি দরুদ পাঠ করুন।", "জুমার দিন আসরের শেষ মুহূর্তে দোয়া কবুলের বিশেষ মুহূর্তটি খুঁজে নিয়ে দোয়া করুন।", "হে আল্লাহ, আমাদের এই জুমাকে বরকতময় করুন, এতে আমাদেরকে ক্ষমা করুন এবং আমাদের প্রতি দয়া করুন।"]}, "ha": {"title": "Addu''o''in Ranar Jumma''a", "duas": ["Ka yawaita salati ga Annabi (SAW) a ranar Jumma''a da dararta.", "Ka nemi sa''ar karbar addu''a a lokacin karshen la''asar ranar Jumma''a, ka yi addu''a a wannan lokacin.", "Ya Allah, ka sanya wannan Jumma''armu mai albarka, ka gafarta mana a cikinta, kuma ka yi mana rahama."]}}}, {"id": "ramadan", "title": "أدعية رمضان وليلة القدر", "icon": "🌙", "duas": ["اللهم إنك عفو تحب العفو فاعف عني", "اللهم بلغنا رمضان، وأعنّا فيه على صيامه وقيامه", "اللهم اجعلنا فيه من عتقائك من النار", "اللهم اقبل صيامنا وقيامنا، وتقبل منا صالح الأعمال"], "translations": {"en": {"title": "Ramadan and Laylat al-Qadr Supplications", "duas": ["O Allah, You are Pardoning and You love pardon, so pardon me.", "O Allah, let us reach Ramadan, and help us therein to fast and to pray at night.", "O Allah, make us among those You free from the Fire in it.", "O Allah, accept our fasting and our night prayer, and accept from us our righteous deeds."]}, "fr": {"title": "Invocations du Ramadan et de la Nuit du Destin", "duas": ["Ô Allah, Tu es Celui qui pardonne et Tu aimes le pardon, alors pardonne-moi.", "Ô Allah, fais-nous atteindre le Ramadan, et aide-nous à en jeûner et à en prier les nuits.", "Ô Allah, fais de nous, en ce mois, ceux que Tu affranchis du Feu.", "Ô Allah, accepte notre jeûne et nos prières nocturnes, et accepte de nous nos bonnes œuvres."]}, "ur": {"title": "رمضان اور شبِ قدر کی دعائیں", "duas": ["اے اللہ! بیشک تو معاف کرنے والا ہے اور معافی کو پسند کرتا ہے، پس مجھے معاف فرما دے۔", "اے اللہ! ہمیں رمضان تک پہنچا، اور اس کے روزے اور قیام میں ہماری مدد فرما۔", "اے اللہ! ہمیں اس میں جہنم سے آزاد کیے جانے والوں میں شامل فرما۔", "اے اللہ! ہمارے روزے اور قیام کو قبول فرما، اور ہمارے نیک اعمال قبول فرما۔"]}, "id": {"title": "Doa-doa Ramadan dan Lailatul Qadar", "duas": ["Ya Allah, sesungguhnya Engkau Maha Pemaaf dan mencintai pemaafan, maka maafkanlah aku.", "Ya Allah, sampaikanlah kami pada bulan Ramadan, dan bantulah kami di dalamnya untuk berpuasa dan melaksanakan salat malam.", "Ya Allah, jadikanlah kami termasuk orang-orang yang Engkau bebaskan dari neraka di bulan itu.", "Ya Allah, terimalah puasa dan salat malam kami, dan terimalah dari kami amal-amal saleh kami."]}, "ms": {"title": "Doa-Doa Ramadan dan Lailatulqadar", "duas": ["Ya Allah, sesungguhnya Engkau Maha Pengampun, Engkau mencintai keampunan, maka ampunilah daku.", "Ya Allah, sampaikanlah kami ke bulan Ramadan, dan bantulah kami padanya untuk berpuasa dan mendirikan qiamullail.", "Ya Allah, jadikanlah kami antara mereka yang Engkau bebaskan daripada api neraka pada bulan tersebut.", "Ya Allah, terimalah puasa dan qiamullail kami, serta terimalah daripada kami segala amalan soleh."]}, "hi": {"title": "रमज़ान और शब-ए-क़द्र की दुआएं", "duas": ["हे अल्लाह! बेशक तू माफ़ करने वाला है, माफ़ी को पसंद करता है, तो मुझे माफ़ कर दे।", "हे अल्लाह! हमें रमज़ान तक पहुँचा, और उसमें रोज़ा रखने और क़याम करने में हमारी मदद फ़रमा।", "हे अल्लाह! हमें इसमें उन लोगों में शामिल कर जिन्हें तू जहन्नम की आग से आज़ाद करता है।", "हे अल्लाह! हमारा रोज़ा और हमारा क़याम क़बूल फ़रमा, और हमसे नेक आमाल क़बूल फ़रमा।"]}, "tr": {"title": "Ramazan ve Kadir Gecesi Duaları", "duas": ["Allah''ım! Sen affedicisin, affetmeyi seversin; beni affet.", "Allah''ım! Bizi Ramazan''a ulaştır, orucunu ve gece namazını eda etmede bize yardım et.", "Allah''ım! Bizi bu ayda cehennem ateşinden azat ettiklerinden eyle.", "Allah''ım! Orucumuzu ve gece namazımızı kabul et, salih amellerimizi bizden kabul buyur."]}, "bn": {"title": "রমজান ও লাইলাতুল কদরের দোয়া", "duas": ["হে আল্লাহ, নিশ্চয় আপনি ক্ষমাশীল, ক্ষমা করতে ভালোবাসেন, সুতরাং আমাকে ক্ষমা করে দিন।", "হে আল্লাহ, আমাদেরকে রমজান পর্যন্ত পৌঁছে দিন, এবং এতে রোজা রাখা ও রাতের নামাজ আদায়ে আমাদেরকে সাহায্য করুন।", "হে আল্লাহ, এই মাসে আমাদেরকে জাহান্নাম থেকে আপনার মুক্তিপ্রাপ্তদের অন্তর্ভুক্ত করুন।", "হে আল্লাহ, আমাদের রোজা ও রাতের নামাজ কবুল করুন, এবং আমাদের সৎ আমলসমূহ কবুল করুন।"]}, "ha": {"title": "Addu''o''in Ramadana Da Laylatul Qadr", "duas": ["Ya Allah, lallai Kai Mai yafewa ne, kana son yafewa, saboda haka ka yafe mini.", "Ya Allah, ka kai mu Ramadana, kuma ka taimake mu a cikinsa a kan azuminsa da tsayuwar dare.", "Ya Allah, ka sanya mu a cikinsa daga cikin wadanda ka ''yantar daga Wuta.", "Ya Allah, ka karbi azuminmu da tsayuwar darenmu, kuma ka karbi ayyukanmu na kwarai daga gare mu."]}}}]',
    updated_at = now()
where id = 1;
